TEST(ResourceAddressedExecutionKernelTest,
     StopCancelsHeldPreparationWithoutDispatchingAStopStageOrMotion) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  engine.defer_prepare_completion = true;
  auto kernel_heap_test_owner = make_claimed_kernel(
      {registration(
          make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, default_journal,
      ResourceAddressedExecutionKernelConfig{kTestApplicationStartId,
                                             CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;

  const auto accepted = kernel.execute(motion_operation("request.motion.cancel-prepare"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  const auto stopped =
      kernel.stop(stop_request("request.stop.cancel-prepare", accepted.value(), 1U));
  ASSERT_TRUE(wait_until([&] { return engine.cancel_prepared_motion_calls == 1; }));
  EXPECT_EQ(engine.dispatch_prepared_motion_calls, 0);
  EXPECT_EQ(engine.execute_calls, 0);
  EXPECT_EQ(engine.translate_stop_stage_calls.load(), 0);
  ASSERT_TRUE(wait_until([&] {
    const auto status = kernel.read_stop(stopped.event_id);
    return status.ok() && status.value().complete;
  }));

  // One covered participant, contained before dispatch with no stage run.
  const auto status = kernel.read_stop(stopped.event_id);
  ASSERT_TRUE(status.ok()) << status.error().message;
  EXPECT_EQ(status.value().result, StopEventResult::kStopped);
  ASSERT_EQ(status.value().covered.size(), 1U);
  EXPECT_EQ(status.value().covered.front().phase, StopPhase::kStopped);
  EXPECT_FALSE(status.value().covered.front().containing_stage_index.has_value());
  const auto operation = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(operation.ok()) << operation.error().message;
  EXPECT_EQ(operation.value().state, OperationStateKind::kStopped);
  ASSERT_TRUE(operation.value().participants.front().terminal_fact);
  EXPECT_EQ(operation.value().participants.front().terminal_fact->kind,
            ParticipantExecutionFactKind::kCancelledBeforeDispatch);
  EXPECT_EQ(operation.value().participants.front().terminal_fact->effect,
            ParticipantEffectKnowledge::kNoEffect);
  EXPECT_EQ(engine.participant_stop_settlement_calls, 1);
  const auto recovery = kernel.get_operation_recovery_assessment(accepted.value().operation_id);
  ASSERT_TRUE(recovery.ok()) << recovery.error().message;
  EXPECT_EQ(recovery.value().assessment.recovery_class, RecoveryClass::kOrdinaryOperatorStop);
  EXPECT_EQ(recovery.value().assessment.status, RecoveryAssessmentStatus::kRetryReady);

  const auto reset =
      kernel.reset(control_request("request.reset.cancelled-prepare", accepted.value(),
                                   operation.value().operation_revision.value()));
  ASSERT_TRUE(reset.ok()) << reset.error().message;
  ASSERT_TRUE(wait_until([&] {
    return engine.certified_reset_calls.load() == 1 &&
           kernel.resource_snapshot().front().state == ResourceSlotState::kFree;
  }));
  EXPECT_EQ(engine.translate_stop_stage_calls.load(), 0);

  engine.defer_prepare_completion = false;
  engine.next_execution_id = 42U;
  engine.next_execute_result = Result<std::uint64_t>::Ok(42U);
  const auto next = kernel.execute(motion_operation("request.after-cancelled-prepare-reset"));
  ASSERT_TRUE(next.ok()) << next.error().message;
  EXPECT_TRUE(wait_until([&] { return engine.execute_calls.load() == 1; }));
}

TEST(ResourceAddressedExecutionKernelTest,
     StopReconcilesPreparationTerminalPublishedBeforeCancellation) {
  for (const auto terminal_state : {ExecutionState::kStopped, ExecutionState::kFailed}) {
    SCOPED_TRACE(to_string(terminal_state));
    FakeClock clock;
    ManualScheduler scheduler;
    FakeParticipantEngine engine;
    engine.defer_prepare_completion = true;
    // The worker may publish its terminal as soon as acceptance fences
    // dispatch, before the aggregate reducer has initialized participant work.
    // No repeat event is available from idempotent CancelPreparedMotion.
    engine.status_at_stop_fence = ExecutionStatus{};
    engine.status_at_stop_fence->state = terminal_state;
    engine.status_at_stop_fence->execution_id = engine.next_execution_id;
    auto kernel_heap_test_owner = make_claimed_kernel(
        {registration(
            make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
            engine)},
        clock, scheduler, default_journal,
        {kTestApplicationStartId, CellId("cell.test"), 8U});
    auto& kernel = *kernel_heap_test_owner;
    const auto accepted = kernel.execute(motion_operation("request.early-terminal"));
    ASSERT_TRUE(accepted.ok()) << accepted.error().message;
    const auto stopped =
        kernel.stop(stop_request("request.early-terminal.stop", accepted.value(), 1U));
    const auto expected = terminal_state == ExecutionState::kStopped
                              ? StopEventResult::kStopped
                              : StopEventResult::kSomeFailed;
    const auto settled = wait_until(
        [&] {
          const auto result = kernel.read_stop(stopped.event_id);
          return result.ok() && result.value().result == expected;
        },
        std::chrono::seconds(1));
    EXPECT_TRUE(settled);
    // A failed outcome raises the failed-Stop Halt (F1), whose re-attempt
    // cancels the same preparation once more.
    if (terminal_state == ExecutionState::kStopped)
      EXPECT_EQ(engine.cancel_prepared_motion_calls, 1);
    else
      EXPECT_GE(engine.cancel_prepared_motion_calls, 1);
    EXPECT_EQ(engine.dispatch_prepared_motion_calls, 0);
    EXPECT_EQ(engine.translate_stop_stage_calls.load(), 0);
    EXPECT_EQ(engine.participant_stop_settlement_calls,
              terminal_state == ExecutionState::kStopped ? 1 : 0);
    if (!settled) {
      // Keep the failure, but release the pending fixture so independent
      // cases still run instead of aborting during Kernel destruction.
      engine.emit_transition(terminal_state, terminal_state);
      EXPECT_TRUE(wait_until([&] {
        return kernel.read_stop(stopped.event_id).value().result == expected;
      }));
    }
  }
}

TEST(ResourceAddressedExecutionKernelTest,
     CancellationAcknowledgementOrAnotherExecutionCannotProveSettlement) {
  for (const bool unrelated_terminal : {false, true}) {
    SCOPED_TRACE(unrelated_terminal);
    FakeClock clock;
    ManualScheduler scheduler;
    FakeParticipantEngine engine;
    engine.defer_prepare_completion = true;
    engine.prepared_cancel_terminal_state = ExecutionState::kValidating;
    engine.status_at_stop_fence = ExecutionStatus{};
    engine.status_at_stop_fence->state =
        unrelated_terminal ? ExecutionState::kStopped : ExecutionState::kValidating;
    engine.status_at_stop_fence->execution_id = engine.next_execution_id + unrelated_terminal;
    auto kernel_heap_test_owner = make_claimed_kernel(
        {registration(
            make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
            engine)},
        clock, scheduler, default_journal,
        {kTestApplicationStartId, CellId("cell.test"), 8U});
    auto& kernel = *kernel_heap_test_owner;
    const auto accepted = kernel.execute(motion_operation("request.unsettled-prepare"));
    ASSERT_TRUE(accepted.ok()) << accepted.error().message;
    const auto stopped =
        kernel.stop(stop_request("request.unsettled-prepare.stop", accepted.value(), 1U));
    // The never-dispatched goal's Stop closes at once, but neither the
    // cancellation acknowledgement nor another execution's terminal is the
    // participant's settlement: that waits for its own cancellation terminal.
    EXPECT_TRUE(wait_until([&] {
      return kernel.read_stop(stopped.event_id).value().result == StopEventResult::kStopped;
    }));
    EXPECT_EQ(engine.cancel_prepared_motion_calls, 1);
    EXPECT_FALSE(wait_until([&] { return engine.participant_stop_settlement_calls.load() != 0; },
                            std::chrono::milliseconds(100)));
    engine.emit_transition(ExecutionState::kValidating, ExecutionState::kStopped);
    EXPECT_TRUE(wait_until([&] { return engine.participant_stop_settlement_calls.load() == 1; }));
    EXPECT_EQ(kernel.read_stop(stopped.event_id).value().result, StopEventResult::kStopped);
    EXPECT_EQ(engine.dispatch_prepared_motion_calls, 0);
    EXPECT_EQ(engine.translate_stop_stage_calls.load(), 0);
  }
}

TEST(ResourceAddressedExecutionKernelTest,
     PreparedCancellationFailurePublishesUnsettledWithoutPhysicalStop) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  engine.defer_prepare_completion = true;
  engine.prepared_cancel_terminal_state = ExecutionState::kValidating;
  engine.cancel_prepared_motion_hook = [] { throw std::runtime_error("cancel failed"); };
  auto kernel_heap_test_owner = make_claimed_kernel(
      {registration(
          make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;
  const auto operation = kernel.execute(motion_operation("request.cancel-deadline"));
  ASSERT_TRUE(operation.ok());
  const auto stopped =
      kernel.stop(stop_request("request.cancel-deadline.stop", operation.value(), 1U));
  EXPECT_TRUE(wait_until([&] { return engine.cancel_prepared_motion_calls >= 1; }));
  const bool finished = wait_until(
      [&] { return kernel.read_stop(stopped.event_id).value().complete; },
      std::chrono::milliseconds(500));
  EXPECT_TRUE(finished);
  if (finished) {
    const auto status = kernel.read_stop(stopped.event_id).value();
    EXPECT_EQ(status.result, StopEventResult::kSomeFailed);
    ASSERT_EQ(status.covered.size(), 1U);
    EXPECT_EQ(status.covered.front().phase, StopPhase::kFailed);
    EXPECT_FALSE(status.covered.front().containing_stage_index.has_value());
    const auto state = kernel.get_operation_state(operation.value().operation_id).value();
    ASSERT_TRUE(state.participants.front().terminal_error.has_value());
    EXPECT_EQ(state.participants.front().terminal_error->details.at("reason"),
              "prepared_motion_cancel_threw");
    EXPECT_FALSE(state.participants.front().terminal_fact);
    // No cell-wide latch from component state (none was observed failing).
    EXPECT_FALSE(kernel.get_cell_latch().latched);
  }
  // Drain the fixture without turning an earlier EXPECT into a pass.
  engine.emit_transition(ExecutionState::kValidating, ExecutionState::kStopped);
  if (finished) {
    EXPECT_EQ(kernel.read_stop(stopped.event_id).value().result, StopEventResult::kSomeFailed);
  }
  EXPECT_EQ(engine.dispatch_prepared_motion_calls, 0);
  EXPECT_EQ(engine.translate_stop_stage_calls.load(), 0);
}

TEST(ResourceAddressedExecutionKernelTest,
     StopClosesAtOnceForANeverDispatchedGoalWhoseCancelHasNotReturned) {
  // A Stop does not wait, with no time limit, for the cancel of a goal
  // that was never dispatched. Nothing moved: the Stop closes at once and the
  // cancellation is tidied up on its own late terminal. No Stop deadline
  // is involved either way.
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  engine.defer_prepare_completion = true;
  engine.prepared_cancel_terminal_state = ExecutionState::kValidating;
  auto kernel_heap_test_owner = make_claimed_kernel(
      {registration(
          make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;
  const auto operation = kernel.execute(motion_operation("request.cancel-not-returned"));
  ASSERT_TRUE(operation.ok());
  const auto stopped =
      kernel.stop(stop_request("request.cancel-not-returned.stop", operation.value(), 1U));
  // The FakeClock never advances: only an immediate close can finish the Stop.
  ASSERT_TRUE(wait_until([&] {
    return kernel.read_stop(stopped.event_id).value().result == StopEventResult::kStopped;
  }));
  EXPECT_EQ(engine.cancel_prepared_motion_calls, 1);
  EXPECT_EQ(engine.participant_stop_settlement_calls, 0);
  const auto status = kernel.read_stop(stopped.event_id).value();
  ASSERT_EQ(status.covered.size(), 1U);
  EXPECT_EQ(status.covered.front().phase, StopPhase::kStopped);
  EXPECT_FALSE(status.covered.front().escalated);
  EXPECT_FALSE(status.covered.front().containing_stage_index.has_value());
  auto state = kernel.get_operation_state(operation.value().operation_id).value();
  EXPECT_EQ(state.state, OperationStateKind::kStopped);
  EXPECT_FALSE(kernel.get_cell_latch().latched);

  // Until the late cancel reply, the participant is still borrowed: cleanup
  // cannot overtake it.
  const auto early_reset = kernel.reset(control_request(
      "request.cancel-not-returned.early-reset", operation.value(),
      state.operation_revision.value()));
  ASSERT_FALSE(early_reset.ok());
  EXPECT_EQ(early_reset.error().details.at("reason"), "operation_effect_in_flight");
  // Non-terminal feedback is not the cancellation's return.
  engine.emit_transition(ExecutionState::kValidating, ExecutionState::kValidating);
  EXPECT_FALSE(wait_until([&] { return engine.participant_stop_settlement_calls.load() != 0; },
                          std::chrono::milliseconds(100)));
  engine.emit_transition(ExecutionState::kValidating, ExecutionState::kStopped);
  EXPECT_TRUE(wait_until([&] { return engine.participant_stop_settlement_calls.load() == 1; }));
  EXPECT_EQ(engine.dispatch_prepared_motion_calls, 0);
  EXPECT_EQ(engine.translate_stop_stage_calls.load(), 0);
  EXPECT_EQ(engine.execute_calls, 0);
}

TEST(ResourceAddressedExecutionKernelTest,
     CarriedObjectLostStopEndsTheStoppedMotionWithItsTypedCause) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  auto kernel_heap_test_owner = make_claimed_kernel(
      {registration(
          make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;
  const auto operation = kernel.execute(motion_operation("request.carried-lost"));
  ASSERT_TRUE(operation.ok()) << operation.error().message;
  engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
  auto intent = stop_request("request.carried-lost.stop", operation.value(), 1U);
  intent.request_context.source_label = "manager.carried_object_lost";
  intent.reason = "carried_object_lost";
  const auto stopped = kernel.stop(intent);
  ASSERT_TRUE(wait_until([&] {
    return kernel.read_stop(stopped.event_id).value().result == StopEventResult::kStopped;
  }));
  // With `stop_motion: true`, the Program's own Stop, settled at its first
  // stage, leaves the moving motion Stopped with the typed cause its node
  // fails with, and the requester class is the Program's, not the operator's.
  const auto state = kernel.get_operation_state(operation.value().operation_id).value();
  EXPECT_EQ(state.state, OperationStateKind::kStopped);
  ASSERT_EQ(state.participants.size(), 1U);
  EXPECT_EQ(state.participants.front().state, OperationStateKind::kStopped);
  ASSERT_TRUE(state.participants.front().terminal_error.has_value());
  EXPECT_EQ(state.participants.front().terminal_error->code, "carried_object_lost");
  ASSERT_TRUE(state.participants.front().terminal_fact.has_value());
  EXPECT_EQ(state.participants.front().terminal_fact->kind,
            ParticipantExecutionFactKind::kPreemptedByAddressedStop);
  EXPECT_EQ(state.participants.front().terminal_fact->effect,
            ParticipantEffectKnowledge::kEffectSettled);
  EXPECT_FALSE(kernel.get_cell_latch().latched);
  const auto recovery = kernel.get_operation_recovery_assessment(operation.value().operation_id);
  ASSERT_TRUE(recovery.ok()) << recovery.error().message;
  EXPECT_EQ(recovery.value().assessment.recovery_class, RecoveryClass::kOrdinaryProgramStop);
  EXPECT_STREQ(recovery_class_name(recovery.value().assessment.recovery_class),
               "ordinary_program_stop");
}

// The requester is authoritative provenance, never a caller's labels.
// A Stop through the public route (its own transport) that claims a Program
// source is an operator Stop and keeps the operator hold or today's Failed hold.
TEST(ResourceAddressedExecutionKernelTest,
     PublicStopClaimingAProgramSourceStillHoldsAsAnOperatorStop) {
  struct Claim final {
    const char* source;
    const char* reason;
    RequestTransportDTO transport;
  };
  for (const auto& claim : {Claim{"kernel.global_io_rule", "interrupt_fault",
                                  RequestTransportDTO::kHttp},
                            Claim{"kernel.global_io_rule", "interrupt_fault",
                                  RequestTransportDTO::kInternal},
                            Claim{"kernel.io_rule", "motion_interrupt_signal_trip",
                                  RequestTransportDTO::kHttp},
                            Claim{"manager.carried_object_lost", "carried_object_lost",
                                  RequestTransportDTO::kHttp}}) {
    SCOPED_TRACE(std::string(claim.source) + " via transport " +
                 std::to_string(static_cast<int>(claim.transport)));
    FakeClock clock;
    ManualScheduler scheduler;
    FakeParticipantEngine engine;
    auto kernel_heap_test_owner = make_claimed_kernel(
        {registration(
            make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
            engine)},
        clock, scheduler, default_journal,
        {kTestApplicationStartId, CellId("cell.test"), 8U});
    auto& kernel = *kernel_heap_test_owner;
    const auto operation = kernel.execute(motion_operation("request.spoofed"));
    ASSERT_TRUE(operation.ok()) << operation.error().message;
    engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
    auto intent = stop_request("request.spoofed.stop", operation.value(), 1U);
    intent.request_context.source_label = claim.source;
    intent.reason = claim.reason;
    intent.attribution.transport = claim.transport;
    const auto stopped = kernel.stop(intent);
    ASSERT_TRUE(wait_stop_complete(kernel, stopped.event_id));
    const auto state = kernel.get_operation_state(operation.value().operation_id).value();
    const auto recovery =
        kernel.get_operation_recovery_assessment(operation.value().operation_id);
    ASSERT_TRUE(recovery.ok()) << recovery.error().message;
    EXPECT_NE(recovery.value().assessment.recovery_class, RecoveryClass::kOrdinaryProgramStop);
    if (std::string(claim.source) == "manager.carried_object_lost") {
      // The claimed cause stays on the row, but the outcome is today's hold.
      EXPECT_EQ(state.state, OperationStateKind::kInterventionRequired);
      EXPECT_EQ(state.participants.front().state, OperationStateKind::kFailed);
    } else {
      // An ordinary operator Stop: Stopped and held for the operator.
      EXPECT_EQ(state.state, OperationStateKind::kStopped);
      EXPECT_EQ(recovery.value().assessment.recovery_class,
                RecoveryClass::kOrdinaryOperatorStop);
    }
  }
}

