TEST(ResourceAddressedExecutionKernelTest,
     RuntimeCollisionUsesTheAddressedStopOwnerAndDeclaredCoordinatedScopeExactlyOnce) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine first_engine;
  FakeParticipantEngine second_engine;
  second_engine.next_command_result.command_id = second_engine.next_execution_id;
  second_engine.gripper_status.command_id = second_engine.next_execution_id;
  const auto first =
      make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular);
  const auto second = coordinated_occurrence(grouped_command_binding(), "2");
  auto kernel_heap_test_owner = make_unclaimed_kernel(
      {registration(first, first_engine), registration(second, second_engine)}, clock, scheduler,
      default_journal, {kTestApplicationStartId, CellId("cell.test"), 16U});
  auto& kernel = *kernel_heap_test_owner;

  const auto accepted =
      kernel.execute(grouped_motion_commands_operation("request.motion.coordinated.collision"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message << ": "
                             << accepted.error().details.at("reason");
  first_engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
  second_engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);

  first_engine.emit_collision({{"contact_a", "component/robot/body/tool/collision/0"},
                               {"contact_b", "scene/workpiece/shape/0"}});
  std::optional<StopEventId> stop_id;
  ASSERT_TRUE(wait_until([&] {
    const auto operation = kernel.get_operation_state(accepted.value().operation_id);
    if (!operation.ok() || !operation.value().stop_event_id.has_value()) {
      return false;
    }
    stop_id = operation.value().stop_event_id;
    return first_engine.translate_stop_stage_calls.load() == 1 &&
           second_engine.translate_stop_stage_calls.load() == 1;
  }));
  ASSERT_TRUE(stop_id.has_value());
  ASSERT_TRUE(first_engine.last_stop_stage.has_value());
  ASSERT_TRUE(second_engine.last_stop_stage.has_value());
  for (const auto* stage : {&*first_engine.last_stop_stage}) {
    ASSERT_TRUE(stage->participant_stop_plan.participant_stop_profile.has_value());
    EXPECT_EQ(stage->participant_stop_plan.participant_stop_profile->profile_id,
              "fault_spring_back_hold");
    EXPECT_EQ(stage->participant_stop_plan.participant_stop_profile->stop_mode,
              MotionInterruptStopMode::kSpringBackHold);
    EXPECT_EQ(stage->participant_stop_plan.participant_stop_profile_purpose,
              ParticipantStopProfilePurposeDTO::kFault);
    EXPECT_FALSE(stage->participant_stop_plan.motion_interrupt_scope_id.has_value());
  }
  EXPECT_FALSE(second_engine.last_stop_stage->participant_stop_plan.participant_stop_profile);
  EXPECT_EQ(second_engine.last_stop_stage->participant_stop_plan.participant_stop_profile_purpose,
            ParticipantStopProfilePurposeDTO::kOrdinary);
  EXPECT_EQ(first_engine.last_stop_stage->operation_id, accepted.value().operation_id);
  EXPECT_EQ(second_engine.last_stop_stage->operation_id, accepted.value().operation_id);
  EXPECT_EQ(first_engine.last_stop_stage->stop_event_id, *stop_id);
  EXPECT_EQ(second_engine.last_stop_stage->stop_event_id, *stop_id);
  ASSERT_TRUE(wait_until([&] {
    const auto status = kernel.read_stop(*stop_id);
    return status.ok() && status.value().result == StopEventResult::kStopped;
  }));

  // One runtime-collision event over the operation's two participants, each
  // contained by its own dispatched stage.
  const auto status = kernel.read_stop(*stop_id);
  ASSERT_TRUE(status.ok()) << status.error().message;
  EXPECT_EQ(status.value().requested, StopKind::kRuntimeCollision);
  EXPECT_EQ(status.value().widen_reason, StopWidenReason::kNone);
  ASSERT_EQ(status.value().covered.size(), 2U);
  EXPECT_TRUE(std::all_of(status.value().covered.begin(), status.value().covered.end(),
                          [](const auto& entry) {
                            return entry.started && entry.containing_stage_index.has_value();
                          }));
  // The event stream's operations table names the runtime monitor's Stop
  // from the Stop ring (OD-205 (b)).
  const auto table = kernel.get_operation_table();
  const auto listed = std::find_if(
      table.faulted.begin(), table.faulted.end(),
      [&](const auto& entry) { return entry.operation_id == accepted.value().operation_id; });
  ASSERT_NE(listed, table.faulted.end());
  EXPECT_EQ(listed->stop_event_id, stop_id);
  ASSERT_TRUE(listed->runtime_monitor_stop.has_value());
  EXPECT_EQ(listed->runtime_monitor_stop->reason.view(), "runtime_collision_fault");
  EXPECT_EQ(listed->runtime_monitor_stop->source_label.view(), "kernel.runtime_collision");
  EXPECT_EQ(listed->runtime_monitor_stop->request_key, status.value().request_key);

  second_engine.emit_collision();
  EXPECT_EQ(first_engine.translate_stop_stage_calls.load(), 1);
  EXPECT_EQ(second_engine.translate_stop_stage_calls.load(), 1);
}

