TEST(ResourceAddressedExecutionKernelTest, UsesOneInjectedGateForTheActualSlotTableReservation) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeResourceAdmissionGate gate;
  auto kernel_heap_test_owner = make_claimed_kernel(
      {registration(
          make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, default_journal,
      ResourceAddressedExecutionKernelConfig{
          kTestApplicationStartId, CellId("cell.test"), 8U, {}, &gate});
  auto& kernel = *kernel_heap_test_owner;

  const auto blocked = kernel.execute(motion_operation());
  ASSERT_FALSE(blocked.ok());
  EXPECT_EQ(blocked.error().details.at("reason"), "configuration_fence_held");
  EXPECT_EQ(gate.reserve_calls, 1);
  EXPECT_EQ(engine.execute_calls, 0);
  const auto blocked_slots = kernel.resource_snapshot();
  ASSERT_EQ(blocked_slots.size(), 1U);
  EXPECT_EQ(blocked_slots.front().state, ResourceSlotState::kFree);

  const auto admission =
      kernel.resource_admission_table()->admission_snapshot({ResourceId("robot.joint_1")});
  EXPECT_EQ(admission.operation_resource_generation, 0U);
  ASSERT_EQ(admission.active_control_configurations.size(), 1U);
  EXPECT_EQ(admission.affected_queued_operation_count, 0U);
  EXPECT_EQ(admission.affected_active_operation_count, 0U);

  gate.reject_reservation = false;
  const auto accepted = kernel.execute(motion_operation());
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  EXPECT_EQ(gate.reserve_calls, 2);
  EXPECT_EQ(engine.execute_calls, 1);
  const auto admitted =
      kernel.resource_admission_table()->admission_snapshot({ResourceId("robot.joint_1")});
  EXPECT_EQ(admitted.operation_resource_generation, 2U);
  EXPECT_EQ(admitted.affected_queued_operation_count, 0U);
  EXPECT_EQ(admitted.affected_active_operation_count, 1U);
}

TEST(ResourceAddressedExecutionKernelTest,
     StagesUnreadyCandidateConfigurationFactsOnlyUnderTheInjectedApplyFence) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeResourceAdmissionGate gate;
  const auto binding =
      make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular);
  auto kernel_heap_test_owner = make_claimed_kernel(
      {unqualified_registration(binding, engine)}, clock, scheduler, default_journal,
      ResourceAddressedExecutionKernelConfig{
          kTestApplicationStartId, CellId("cell.test"), 8U, {}, &gate});
  auto& kernel = *kernel_heap_test_owner;
  const auto& path = *binding.value().control_path;
  const ConfigurationFenceScopeDTO scope{
      {binding.value().controllable_component_id},
      {{path.control_domain_id, std::nullopt, path.control_domain_revision}},
      {{path.control_binding_id, std::nullopt, path.control_binding_revision}},
      {binding.value().resources.front().resource_id}};
  ASSERT_TRUE(scope.valid());
  EXPECT_TRUE(kernel.resource_admission_table()
                  ->admission_snapshot(scope.resources)
                  .active_control_configurations.empty());

  const auto staged = kernel.stage_current_runtime_configuration_facts_under_apply_fence(scope);
  ASSERT_TRUE(staged.ok()) << staged.error().message;
  const auto admission = kernel.resource_admission_table()->admission_snapshot(scope.resources);
  ASSERT_EQ(admission.active_control_configurations.size(), 1U);
  EXPECT_TRUE(admission.route_published_active_control_configurations.empty());
  EXPECT_EQ(admission.active_control_configurations.front().control_domain_id,
            path.control_domain_id);
  EXPECT_EQ(admission.active_control_configurations.front().active_control_configuration_id,
            path.active_control_configuration_id);
  EXPECT_EQ(admission.active_control_configurations.front().active_control_configuration_generation,
            path.active_control_configuration_generation);
  const auto blocked = kernel.execute(motion_operation());
  ASSERT_FALSE(blocked.ok());
  EXPECT_EQ(blocked.error().details.at("reason"), "runtime_route_publication_required");

  gate.reject_reservation = false;
  const auto unfenced = kernel.stage_current_runtime_configuration_facts_under_apply_fence(scope);
  ASSERT_FALSE(unfenced.ok());
  EXPECT_EQ(unfenced.error().details.at("reason"), "runtime_configuration_staging_fence_missing");
}

TEST(ResourceAddressedExecutionKernelTest,
     ProductBackedResolverAdmitsAnExactProgramBindingOnPinnedPhysicalEngine) {
  FakeClock clock;
  ManualScheduler scheduler;
  clock.set(1234);
  FakeParticipantEngine engine;
  const auto physical =
      make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular);
  auto dynamic_value = physical.value();
  dynamic_value.program_id = ProgramId("program.dynamic");
  dynamic_value.program_revision = ProgramRevision(test_digest('4'));
  dynamic_value.program_binding_id = ProgramBindingId(test_digest('5'));
  auto dynamic = verify_runtime_participant_binding(std::move(dynamic_value));
  ASSERT_TRUE(dynamic.ok()) << dynamic.error().message;

  auto intent = motion_operation("request.dynamic.1");
  intent.program_id = ProgramId("program.dynamic");
  intent.program_revision = ProgramRevision(test_digest('4'));
  intent.program_binding_id = ProgramBindingId(test_digest('5'));
  std::size_t resolver_calls = 0U;
  auto kernel_heap_test_owner = make_claim_ready_kernel(
      {registration(physical, engine)}, clock, scheduler, default_journal,
      ResourceAddressedExecutionKernelConfig{
          kTestApplicationStartId, CellId("cell.test"), 8U,
          [&](const OperationIntentDTO&, const std::size_t,
              const ProgramRunResolutionContext&) -> Result<RuntimeParticipantExecutionRegistration> {
            ++resolver_calls;
            return Result<RuntimeParticipantExecutionRegistration>::Ok(
                registration(dynamic.value(), engine));
          }});
  auto& kernel = *kernel_heap_test_owner;
  // Run equality: the dynamic Program's work names the run the Kernel holds,
  // so the run is claimed and captured for that Program (base: an unclaimed
  // Kernel admitted it).
  establish_program_as(kernel, intent.program_id, intent.program_revision,
                       intent.program_binding_id);

  const auto result = kernel.execute(intent);
  ASSERT_TRUE(result.ok()) << result.error().message;
  EXPECT_EQ(resolver_calls, 1U);
  EXPECT_EQ(engine.execute_calls, 1);
  ASSERT_TRUE(engine.last_execute.has_value());
  EXPECT_EQ(engine.last_execute->binding.program_id, intent.program_id);
  EXPECT_EQ(engine.last_execute->binding.program_binding_id, intent.program_binding_id);
}

// OD-234 (1): the Kernel hands the resolver the held capture's resolution
// context for work of the held run, and nothing for any other work.
TEST(ResourceAddressedExecutionKernelTest,
     ResolverReceivesTheHeldCaptureContextOnlyForTheHeldRun) {
  FakeClock clock;
  ManualScheduler scheduler;
  clock.set(1234);
  FakeParticipantEngine engine;
  const auto physical =
      make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular);
  auto dynamic_value = physical.value();
  dynamic_value.program_id = ProgramId("program.dynamic");
  dynamic_value.program_revision = ProgramRevision(test_digest('4'));
  dynamic_value.program_binding_id = ProgramBindingId(test_digest('5'));
  auto dynamic = verify_runtime_participant_binding(std::move(dynamic_value));
  ASSERT_TRUE(dynamic.ok()) << dynamic.error().message;

  auto intent = motion_operation("request.context.1");
  intent.program_id = ProgramId("program.dynamic");
  intent.program_revision = ProgramRevision(test_digest('4'));
  intent.program_binding_id = ProgramBindingId(test_digest('5'));
  std::vector<ProgramRunResolutionContext> received;
  auto kernel_heap_test_owner = make_claim_ready_kernel(
      {registration(physical, engine)}, clock, scheduler, default_journal,
      ResourceAddressedExecutionKernelConfig{
          kTestApplicationStartId, CellId("cell.test"), 8U,
          [&](const OperationIntentDTO&, const std::size_t,
              const ProgramRunResolutionContext& held_run)
              -> Result<RuntimeParticipantExecutionRegistration> {
            received.push_back(held_run);
            return Result<RuntimeParticipantExecutionRegistration>::Ok(
                registration(dynamic.value(), engine));
          }});
  auto& kernel = *kernel_heap_test_owner;
  const ProgramRunResolutionContext context = std::make_shared<const int>(234);
  establish_program_as(kernel, intent.program_id, intent.program_revision,
                       intent.program_binding_id, std::nullopt, std::nullopt, context);
  EXPECT_EQ(kernel.program_run_resolution_context(ProgramRunNumber(1U)), context);
  EXPECT_FALSE(kernel.program_run_resolution_context(ProgramRunNumber(2U)));
  EXPECT_FALSE(kernel.program_run_resolution_context(std::nullopt));

  const auto result = kernel.execute(intent);
  ASSERT_TRUE(result.ok()) << result.error().message;
  ASSERT_EQ(received.size(), 1U);
  EXPECT_EQ(received.front(), context);

  // Work that names no run (refused after resolution here) gets none.
  auto manual = intent;
  manual.request_context.request_key = TestRequestKey("request.context.2");
  manual.program_run_id.reset();
  for (auto& participant : manual.participants) participant.execution_scope.reset();
  EXPECT_FALSE(kernel.execute(manual).ok());
  ASSERT_EQ(received.size(), 2U);
  EXPECT_FALSE(received.back());
}

// OD-235: the engine takes the Stop plans the Kernel built in the same call as
// they are, so the Kernel's plans are pinned here: every plan handed to the
// engine is exactly the plan of the registration's operator and fault
// profiles, for a single motion and for the motion of coordinated work.
void ExpectHandedStopPlansExact(const ResolvedPreparedMotionExecutionRequestDTO& request,
                                const RuntimeParticipantExecutionRegistration& registered,
                                const OperationIntentDTO& intent,
                                const OperationParticipantId& participant_id) {
  ASSERT_TRUE(registered.stop_readiness);
  ASSERT_TRUE(registered.default_operator_stop_profile);
  ASSERT_TRUE(registered.default_fault_stop_profile);
  EXPECT_EQ(request.execution_request.binding.participant_id, participant_id);
  const auto make = [&](const MotionInterruptStopProfileDTO& profile,
                        const ParticipantStopProfilePurposeDTO purpose) {
    return MakePreparedParticipantStopPlan(
        registered.stop_readiness->value().resolved_stop_base_plan,
        PreparedParticipantStopPlanContextDTO{
            participant_id.operation_id, OperationRevision(1U), participant_id,
            intent.program_id, intent.program_revision, intent.program_binding_id,
            intent.program_run_id, profile, purpose, std::nullopt,
            registered.stop_node_category},
        registered.binding.value().resources, registered.retained_default_stop_limits);
  };
  const auto ordinary =
      make(*registered.default_operator_stop_profile, ParticipantStopProfilePurposeDTO::kOperator);
  const auto fault =
      make(*registered.default_fault_stop_profile, ParticipantStopProfilePurposeDTO::kFault);
  ASSERT_TRUE(ordinary.ok()) << ordinary.error().message;
  ASSERT_TRUE(fault.ok()) << fault.error().message;
  ASSERT_TRUE(request.ordinary_stop_plan);
  ASSERT_TRUE(request.fault_stop_plan);
  EXPECT_EQ(*request.ordinary_stop_plan, ordinary.value());
  EXPECT_EQ(*request.fault_stop_plan, fault.value());
}

TEST(ResourceAddressedExecutionKernelTest, HandedStopPlansAreExactlyTheRegistrationsPlans) {
  {
    SCOPED_TRACE("single motion");
    FakeClock clock;
    ManualScheduler scheduler;
    FakeOperationJournal journal;
    FakeParticipantEngine engine;
    const auto registered = registration(
        make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular), engine);
    auto kernel_heap_test_owner = make_claimed_kernel(
        {registered}, clock, scheduler, journal,
        {kTestApplicationStartId, CellId("cell.test"), 8U});
    auto& kernel = *kernel_heap_test_owner;
    const auto intent = motion_operation("request.plans.single");
    const auto accepted = kernel.execute(intent);
    ASSERT_TRUE(accepted.ok()) << accepted.error().message;
    ASSERT_TRUE(engine.last_prepared_request);
    ExpectHandedStopPlansExact(*engine.last_prepared_request, registered, intent,
                               OperationParticipantId{accepted.value().operation_id, 1U});
  }
  {
    SCOPED_TRACE("coordinated work");
    FakeClock clock;
    ManualScheduler scheduler;
    FakeOperationJournal journal;
    FakeParticipantEngine first_engine;
    FakeParticipantEngine second_engine;
    const auto first =
        make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular);
    const ProgramCommandSchemaRefDTO schema{
        CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
        CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
    const auto second =
        coordinated_occurrence(make_binding("gripper.target", "tool.gripper.command",
                                            CoordinateKind::kLinear, schema),
                               "2");
    const auto registered = registration(first, first_engine);
    auto kernel_heap_test_owner = make_unclaimed_kernel(
        {registered, registration(second, second_engine)}, clock, scheduler, journal,
        {kTestApplicationStartId, CellId("cell.test"), 16U});
    auto& kernel = *kernel_heap_test_owner;
    const auto intent = coordinated_motion_command_operation("request.plans.coordinated");
    const auto accepted = kernel.execute(intent);
    ASSERT_TRUE(accepted.ok()) << accepted.error().message;
    ASSERT_TRUE(first_engine.last_prepared_request);
    ExpectHandedStopPlansExact(*first_engine.last_prepared_request, registered, intent,
                               OperationParticipantId{accepted.value().operation_id, 1U});
  }
}

