TEST(ResourceAddressedExecutionKernelTest, UnconfirmedPneumaticDeliveryIsFinalConsumableFailure) {
  FinalPneumaticTestBackend backend;
  backend.reject_delivery = true;
  FakeClock clock;
  ManualScheduler scheduler;
  GripperParticipantEngine gripper(backend, clock);
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  auto row = LogicalGripperRegistration(make_binding("gripper.target", "tool.gripper.command",
      CoordinateKind::kLinear, schema), gripper);
  auto kernel_heap_test_owner = make_claimed_kernel({row}, clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;
  const auto accepted = kernel.execute(command_operation());
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  const auto state = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(state.ok());
  EXPECT_EQ(state.value().state, OperationStateKind::kFailed);
  ASSERT_TRUE(state.value().participants.front().terminal_error);
  EXPECT_EQ(state.value().participants.front().terminal_error->code, "pneumatic_delivery_timeout");
  EXPECT_EQ(state.value().participants.front().terminal_error->details.at("pneumatic_transaction_final"), "true");
  EXPECT_FALSE(kernel.get_cell_latch().latched);
  backend.finish(false);  // a late provider Success cannot rewrite the Kernel final Failure
  ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
  EXPECT_EQ(kernel.get_operation_state(accepted.value().operation_id).value().state, OperationStateKind::kFailed);
  ASSERT_TRUE(kernel.acknowledge_completed(control_request(
      "pneumatic.failure.ack", accepted.value(), state.value().operation_revision.value())).ok());
  EXPECT_EQ(backend.opens, 0);
  EXPECT_EQ(backend.closes, 0);  // no cell Reset, physical cancel or fault path
  EXPECT_EQ(backend.commands, 1);
  ASSERT_TRUE(wait_until([&] {
    const auto slots = kernel.resource_snapshot();
    return std::all_of(slots.begin(), slots.end(), [](const auto& slot) {
      return slot.state == ResourceSlotState::kFree && !slot.owner;
    });
  }));
  backend.reject_delivery = false;
  const auto next = kernel.execute(command_operation("pneumatic.rewrite"));
  ASSERT_TRUE(next.ok()) << next.error().message;
  EXPECT_EQ(backend.commands, 2);  // the next command rewrites without Reset
  EXPECT_EQ(kernel.get_operation_state(accepted.value().operation_id).value().state,
            OperationStateKind::kFailed);
}

TEST(ResourceAddressedExecutionKernelTest, FinalPneumaticFailureRemainsFinalWhileCoordinatedSiblingExecutes) {
  FinalPneumaticTestBackend first_backend, second_backend;
  FakeClock clock;
  ManualScheduler scheduler;
  GripperParticipantEngine first_engine(first_backend, clock), second_engine(second_backend, clock);
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  const auto first = make_binding("gripper.target", "tool.gripper.command", CoordinateKind::kLinear, schema);
  const auto second = coordinated_occurrence(first, "2");
  auto kernel_heap_test_owner = make_unclaimed_kernel({LogicalGripperRegistration(first, first_engine),
      LogicalGripperRegistration(second, second_engine)}, clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;
  const auto accepted = kernel.execute(coordinated_command_operation("pneumatic.two"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  first_backend.finish(true);
  ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
  const auto failed = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(failed.ok());
  ASSERT_EQ(failed.value().participants.size(), 2U);
  EXPECT_EQ(failed.value().participants.front().state, OperationStateKind::kFailed);
  EXPECT_EQ(failed.value().participants.back().state, OperationStateKind::kExecuting);
  const auto original_error = failed.value().participants.front().terminal_error;
  first_backend.finish(false);
  ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
  const auto late = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(late.ok());
  EXPECT_EQ(late.value().participants.front().state, OperationStateKind::kFailed);
  EXPECT_EQ(late.value().participants.front().terminal_error, original_error);
  second_backend.finish(false);
  ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
  EXPECT_EQ(kernel.get_operation_state(accepted.value().operation_id).value().state, OperationStateKind::kFailed);
  EXPECT_EQ(first_backend.commands, 1);
  EXPECT_EQ(second_backend.commands, 1);
  EXPECT_FALSE(kernel.get_cell_latch().latched);
}

TEST(ResourceAddressedExecutionKernelTest, PneumaticAcknowledgementDoesNotReopenSharedPositionAdmission) {
  // Genuine Core owners share this unit provider's one admission fence. The
  // position sibling has no admitted transaction in this test; no physical
  // transport/cancel acknowledgement is claimed.
  class SharedBackend final : public IGripperCommandBackend {
   public:
    FinalPneumaticTestBackend pneumatic;
    bool position_closed{};
    GripperCommandStatusDTO position;
    SharedBackend() {
      position.gripper_id = "position.target";
      position.command_id = 55U;
      position.generation = 89U;
      position.revision = 1U;
      position.state = GripperCommandState::kIdle;
    }
    GripperActuationKind gripper_actuation_kind(const std::string& id) const override {
      return id == position.gripper_id ? GripperActuationKind::kPositionCommanded : GripperActuationKind::kPneumatic;
    }
    GripperCommandResultDTO command_gripper(const GripperCommandRequestDTO& request) override {
      if (request.gripper_id != position.gripper_id) return pneumatic.command_gripper(request);
      if (position_closed) return {false, 0U, 0U,
          ErrorDTO{"gripper_admission_closed", "Shared Stop remains in force", {}}};
      return {true, position.command_id, position.generation, std::nullopt};
    }
    GripperCommandStatusDTO get_gripper_status(const std::string& id) const override {
      return id == position.gripper_id ? position : pneumatic.get_gripper_status(id);
    }
    GripperCommandResultDTO mark_gripper_grasp_lost(const std::string&, std::uint64_t,
        std::uint64_t, const std::string&, const std::string&, const std::string&) override { return {}; }
    void invalidate_gripper_commands(const GripperInvalidationReason reason) noexcept override {
      if (reason != GripperInvalidationReason::kStop) pneumatic.invalidate_gripper_commands(reason);
      position_closed = true;
      position.state = GripperCommandState::kIdle;
      ++position.generation;
      ++position.revision;
    }
    void authorize_gripper_commands() noexcept override {
      pneumatic.authorize_gripper_commands();
      position_closed = false;
    }
  } backend;
  FakeClock clock;
  ManualScheduler scheduler;
  GripperParticipantEngine pneumatic_owner(backend, clock), position_owner(backend, clock);
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  const auto binding = make_binding("gripper.target", "tool.gripper.command", CoordinateKind::kLinear, schema);
  auto kernel_heap_test_owner = make_claimed_kernel({LogicalGripperRegistration(binding, pneumatic_owner)},
      clock, scheduler, default_journal, {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;
  // A real Position command's existing scoped Stop closes its moving gate.
  GripperCommandRequestDTO position_before;
  position_before.gripper_id = "position.target";
  ASSERT_TRUE(position_owner.command_gripper(position_before).accepted);
  backend.position.state = GripperCommandState::kExecuting;
  ASSERT_TRUE(position_owner.stop_gripper("position.target", backend.position.command_id,
                                         backend.position.generation).ok());
  const auto accepted = kernel.execute(command_operation("pneumatic.shared"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  // The cell-wide Stop without a hold (today's cell Full Stop).
  const auto stop = kernel.cell_stop(FullStopIntentDTO{
      {TestRequestKey("pneumatic.shared.stop"), "test"}, {}});
  ASSERT_TRUE(wait_until([&] {
    const auto state = kernel.read_stop(stop.event_id);
    return state.ok() && state.value().complete;
  })) << PneumaticStopDiagnostic(kernel, stop.event_id, pneumatic_owner, backend.pneumatic);
  backend.pneumatic.finish(true);
  ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
  const auto state = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(state.ok());
  ASSERT_EQ(state.value().state, OperationStateKind::kFailed);
  ASSERT_TRUE(kernel.acknowledge_completed(control_request("pneumatic.shared.ack", accepted.value(),
      state.value().operation_revision.value())).ok());
  ASSERT_TRUE(wait_until([&] {
    const auto slots = kernel.resource_snapshot();
    return std::all_of(slots.begin(), slots.end(), [](const auto& row) {
      return row.state == ResourceSlotState::kFree && !row.owner;
    });
  }));
  EXPECT_TRUE(backend.position_closed);
  EXPECT_FALSE(backend.pneumatic.get_gripper_status("gripper.target").admission_closed);
  EXPECT_EQ(backend.pneumatic.opens, 0);
  GripperCommandRequestDTO position_request;
  position_request.gripper_id = "position.target";
  EXPECT_FALSE(position_owner.command_gripper(position_request).accepted);
  const auto current = backend.get_gripper_status("position.target");
  ASSERT_TRUE(position_owner.reset_gripper("position.target", current.command_id, current.generation).ok());
  EXPECT_TRUE(position_owner.command_gripper(position_request).accepted);
  EXPECT_EQ(backend.pneumatic.opens, 1); // established explicit Reset, not pneumatic ACK
}

TEST(ResourceAddressedExecutionKernelTest, FocusedGripperReplaysAndSettlesExactBackendCommand) {
  for (const bool hold_dispatch_return : {false, true}) {
    SCOPED_TRACE(hold_dispatch_return);
    class Backend final : public IGripperCommandBackend {
     public:
      mutable std::mutex mutex;
      GripperCommandStatusDTO status;
      GripperCommandRequestDTO last_request;
      std::atomic<int> commands{};
      std::atomic<int> invalidations{};
      std::function<void()> return_hook;
      bool refuse_local_fence{};
      GripperCommandResultDTO command_gripper(const GripperCommandRequestDTO& request) override {
        {
          std::lock_guard lock(mutex);
          ++commands;
          last_request = request;
          status.gripper_id = request.gripper_id;
          status.command_id = 41U;  // deliberately not preparation id 1
          status.generation = 73U;
          status.state = GripperCommandState::kExecuting;
          ++status.revision;
        }
        if (return_hook) return_hook();
        return {true, 41U, 73U, std::nullopt};
      }
      GripperCommandStatusDTO get_gripper_status(const std::string&) const override {
        std::lock_guard lock(mutex);
        return status;
      }
      GripperCommandResultDTO mark_gripper_grasp_lost(const std::string&, std::uint64_t,
                                                      std::uint64_t, const std::string&,
                                                      const std::string&,
                                                      const std::string&) override {
        return {};
      }
      void invalidate_gripper_commands(GripperInvalidationReason) noexcept override {
        std::lock_guard lock(mutex);
        if (!refuse_local_fence) {
          status.state = GripperCommandState::kIdle;
          ++status.generation;
          ++status.revision;
        }
        ++invalidations;
      }
      void authorize_gripper_commands() noexcept override {}
    } backend;
    FakeClock clock;
    ManualScheduler scheduler;
    GripperParticipantEngine gripper(backend, clock);
    const ProgramCommandSchemaRefDTO schema{
        CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
        CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
    auto row = LogicalGripperRegistration(make_binding("gripper.target", "tool.gripper.command",
                                                        CoordinateKind::kLinear, schema), gripper);
    auto kernel_heap_test_owner = make_claimed_kernel(
        {row}, clock, scheduler, default_journal,
        {kTestApplicationStartId, CellId("cell.test"), 8U});
    auto& kernel = *kernel_heap_test_owner;
    HeldSettlementCall dispatch_return;
    if (hold_dispatch_return) backend.return_hook = dispatch_return.Blocker();
    auto executing =
        std::async(std::launch::async, [&] { return kernel.execute(command_operation()); });
    if (hold_dispatch_return) {
      ASSERT_TRUE(dispatch_return.Entered());
    } else {
      ASSERT_EQ(executing.wait_for(std::chrono::seconds(2)), std::future_status::ready);
    }
    const auto stopped = kernel.cell_stop(FullStopIntentDTO{{TestRequestKey("focused.stop"), "test"}, {}});
    ASSERT_EQ(stopped.covered.size(), 1U);
    const auto event_complete = [&] {
      const auto status = kernel.read_stop(stopped.event_id);
      return status.ok() && status.value().complete;
    };
    if (hold_dispatch_return) {
      // As `main`, the gripper's Stop is a fire-and-forget cancel; the
      // Stop does not wait for the still-returning command.
      const bool published = wait_until(event_complete, std::chrono::seconds(1));
      if (!published) dispatch_return.Release();
      ASSERT_TRUE(published);
      EXPECT_EQ(gripper.ObservePreparedCapabilityCommand(1U).value().state,
                ResolvedPreparedCapabilityCommandStateDTO::kDispatchRequested);
      EXPECT_EQ(backend.invalidations.load(), 1);
      EXPECT_FALSE(kernel.get_cell_latch().latched);
    } else {
      ASSERT_TRUE(wait_until(event_complete, std::chrono::seconds(1)));
      // The command already returned: the local settlement's invalidation
      // follows the stage asynchronously.
      ASSERT_TRUE(wait_until([&] { return backend.invalidations.load() == 2; },
                             std::chrono::seconds(5)))
          << backend.invalidations.load();
    }
    const auto stop_readback = kernel.read_stop(stopped.event_id);
    ASSERT_TRUE(stop_readback.ok());
    EXPECT_EQ(stop_readback.value().result, StopEventResult::kStopped);
    ASSERT_EQ(stop_readback.value().covered.size(), 1U);
    EXPECT_EQ(stop_readback.value().covered.front().phase, StopPhase::kStopped);
    EXPECT_TRUE(stop_readback.value().covered.front().containing_stage_index.has_value());
    const auto contained_stage = stop_readback.value().covered.front().containing_stage_index;
    dispatch_return.Release();
    const auto accepted = executing.get();
    ASSERT_TRUE(accepted.ok()) << accepted.error().message;
    const auto prepared = gripper.ObservePreparedCapabilityCommand(1U);
    ASSERT_TRUE(prepared.ok());
    const auto& snapshot = prepared.value();
    ASSERT_TRUE(snapshot.participant && snapshot.controller_goal_id && snapshot.dispatch_result);
    EXPECT_NE(snapshot.preparation_id, snapshot.dispatch_result->command_id);
    const auto replay = [&] {
      return gripper.DispatchPreparedCapabilityCommand(
          snapshot.preparation_id, snapshot.participant->prepared_contract_digest,
          *snapshot.controller_goal_id);
    };
    ASSERT_TRUE(replay().ok());
    EXPECT_EQ(backend.commands.load(), 1);
    EXPECT_FALSE(gripper.CancelPreparedCapabilityCommand(snapshot.preparation_id).ok());
    ASSERT_TRUE(wait_until([&] {
      const auto state = kernel.get_operation_state(accepted.value().operation_id);
      return state.ok() && state.value().state == OperationStateKind::kStopped;
    }));
    EXPECT_EQ(gripper.get_recovery_assessment().execution_id, snapshot.preparation_id);
    EXPECT_EQ(gripper.get_recovery_assessment().status, RecoveryAssessmentStatus::kRetryReady);
    ASSERT_TRUE(replay().ok());  // lost response cannot re-emit after certified Stop
    EXPECT_EQ(backend.commands.load(), 1);
    EXPECT_EQ(backend.invalidations.load(), 2);  // physical containment + local settlement

    // Engine level: the test mints the executed stage request itself, the way
    // the Kernel resolves it (`resolve_participant_stop_stage`), from the
    // prepared participant, the registration and the event: no Kernel access.
    ASSERT_TRUE(contained_stage.has_value());
    const auto& prepared_participant = *snapshot.participant;
    const auto& path = *row.binding.value().control_path;
    const RemainingStopBudgetDTO budget{stopped.event_id, 0, std::nullopt};
    // As the Kernel: the epoch and granularity of the executed stage itself.
    const auto& executed_stage = prepared_participant.controller()
                                     .ordinary_stop_plan.stage_commands.at(*contained_stage)
                                     .resolved_stage;
    const auto stage_request = [&](const ControllerGoalId& goal) {
      return MakeResolvedParticipantStopStage(
          ResolvedParticipantStopStageDTO{stopped.event_id,
                                          prepared_participant.operation_id,
                                          prepared_participant.controller().ordinary_stop_plan.operation_revision,
                                          prepared_participant.controller().ordinary_stop_plan.participant_id,
                                          goal,
                                          row.binding.value().controllable_component_id,
                                          row.binding.value().command_target_id,
                                          row.binding.value().capability_id,
                                          path.control_domain_id,
                                          path.control_domain_revision,
                                          path.control_binding_id,
                                          path.control_binding_revision,
                                          path.active_control_configuration_id,
                                          path.active_control_configuration_generation,
                                          path.controller_topology_id,
                                          path.topology_revision,
                                          path.control_route_id,
                                          std::nullopt,
                                          std::nullopt,
                                          executed_stage.command_target.provider_runtime_epoch,
                                          prepared_participant.resources,
                                          executed_stage.containment_granularity,
                                          path.stop_evidence_policy_id,
                                          path.stop_evidence_policy_revision,
                                          prepared_participant.controller().ordinary_stop_plan,
                                          *contained_stage,
                                          ContentDigest("pending")},
          budget, row.stop_readiness->value().resolved_stop_base_plan, row.binding,
          row.retained_default_stop_limits, row.stop_node_category,
          prepared_participant.resources);
    };
    const auto executed = stage_request(*snapshot.controller_goal_id);
    ASSERT_TRUE(executed.ok()) << executed.error().message;
    // Re-translating the same stage request returns the identical result,
    // with no further invalidation.
    const auto first_translation = gripper.TranslateStopStage(executed.value(), budget, {});
    EXPECT_EQ(first_translation.outcome, ParticipantStopStageOutcomeDTO::kSucceeded);
    EXPECT_FALSE(first_translation.controller_acknowledgement_sequence);
    ASSERT_EQ(first_translation.evidence_items.size(), 1U);
    EXPECT_EQ(first_translation.evidence_items.front().required_class,
              StopEvidenceRequirementKind::kLogicalCancellationNoContinuingEffect);
    EXPECT_EQ(gripper.TranslateStopStage(executed.value(), budget, {}), first_translation);
    EXPECT_EQ(backend.invalidations.load(), 2);
    // A foreign goal or a foreign provider epoch is refused, with no further
    // invalidation.
    for (const bool foreign_goal : {true, false}) {
      auto foreign = executed.value();
      if (foreign_goal) foreign.controller_goal_id = ControllerGoalId{OperationNumber(902U), 1U, 1U};
      else foreign.provider_runtime_epoch = RuntimeEpoch("foreign.provider.epoch");
      EXPECT_TRUE(gripper.TranslateStopStage(foreign, budget, {}).error);
      EXPECT_EQ(backend.invalidations.load(), 2);
    }

    // A separate, never-dispatched preparation can be cancelled and replayed
    // without touching the backend, even when its preparation number matches.
    GripperParticipantEngine cancelled(backend, clock);
    const ResolvedPreparedCapabilityCommandExecutionRequestDTO request{
        snapshot.participant,   row.binding,
        *row.stop_readiness,    row.retained_default_stop_limits,
        row.stop_node_category, backend.last_request};
    const auto pending = cancelled.PrepareCapabilityCommand(request);
    ASSERT_TRUE(pending.ok());
    ASSERT_TRUE(cancelled.CancelPreparedCapabilityCommand(pending.value()).ok());
    const auto exact = cancelled.PrepareCapabilityCommand(request);
    ASSERT_TRUE(exact.ok());
    EXPECT_EQ(exact.value(), pending.value());
    EXPECT_EQ(cancelled.fence_addressed_participant_stop(pending.value()).disposition,
              AddressedParticipantStopFenceDisposition::kEffectPreventedBeforeDispatch);
    EXPECT_FALSE(cancelled
                     .DispatchPreparedCapabilityCommand(
                         pending.value(), snapshot.participant->prepared_contract_digest,
                         *snapshot.controller_goal_id)
                     .ok());
    EXPECT_EQ(backend.commands.load(), 1);
    EXPECT_EQ(backend.invalidations.load(), 2);
    // E2/E11 fence call (1) on a prepared, never-dispatched gripper command
    // (stop state model §3.1, PD-10 (a')): the linearising part alone closes
    // the session gate and reports it; call (2) completes the fence after
    // the Kernel unlock. Nothing reaches the backend and dispatch is refused.
    {
      GripperParticipantEngine fenced(backend, clock);
      const auto prepared_only = fenced.PrepareCapabilityCommand(request);
      ASSERT_TRUE(prepared_only.ok());
      const auto call_one = fenced.fence_addressed_participant_stop(prepared_only.value());
      EXPECT_EQ(call_one.disposition,
                AddressedParticipantStopFenceDisposition::kEffectPreventedBeforeDispatch);
      EXPECT_NE(call_one.closed_gates &
                    static_cast<std::uint8_t>(AddressedParticipantStopFenceGate::kActiveSession),
                0U);
      EXPECT_EQ(backend.invalidations.load(), 2);  // call (1) touches no backend
      fenced.complete_addressed_participant_stop_fence(prepared_only.value(),
                                                       call_one.closed_gates);
      const auto after = fenced.DispatchPreparedCapabilityCommand(
          prepared_only.value(), snapshot.participant->prepared_contract_digest,
          *snapshot.controller_goal_id);
      EXPECT_FALSE(after.ok() && after.value().accepted);
      EXPECT_EQ(backend.commands.load(), 1);
    }
    // A thrown backend dispatch is uncertainty, never pre-dispatch absence.
    // Keep the actual observed target executing and refuse typed containment.
    GripperParticipantEngine uncertain(backend, clock);
    const auto uncertain_preparation = uncertain.PrepareCapabilityCommand(request);
    ASSERT_TRUE(uncertain_preparation.ok());
    backend.return_hook = [] { throw std::runtime_error("actual dispatch return unavailable"); };
    const auto uncertain_return = uncertain.DispatchPreparedCapabilityCommand(
        uncertain_preparation.value(), snapshot.participant->prepared_contract_digest,
        *snapshot.controller_goal_id);
    ASSERT_TRUE(uncertain_return.ok());
    EXPECT_FALSE(uncertain_return.value().accepted);
    EXPECT_TRUE(uncertain_return.value().error);
    EXPECT_EQ(uncertain.ObservePreparedCapabilityCommand(uncertain_preparation.value()).value().state,
              ResolvedPreparedCapabilityCommandStateDTO::kDispatchFailed);
    const auto refused = uncertain.TranslateStopStage(executed.value(), budget, {});
    EXPECT_EQ(refused.attempt_disposition, StopStageAttemptDispositionDTO::kNotDispatched);
    EXPECT_EQ(refused.outcome, ParticipantStopStageOutcomeDTO::kFailed);
    EXPECT_TRUE(refused.error);
    EXPECT_FALSE(refused.controller_acknowledgement_sequence);
    EXPECT_EQ(backend.get_gripper_status(backend.last_request.gripper_id).state,
              GripperCommandState::kExecuting);
    EXPECT_EQ(backend.invalidations.load(), 2);
    backend.return_hook = {};
    // Failed local fencing is distinct from unavailable cancel data.
    GripperParticipantEngine unfenced(backend, clock);
    const auto unfenced_preparation = unfenced.PrepareCapabilityCommand(request);
    ASSERT_TRUE(unfenced_preparation.ok());
    const auto unfenced_dispatch = unfenced.DispatchPreparedCapabilityCommand(
        unfenced_preparation.value(), snapshot.participant->prepared_contract_digest,
        *snapshot.controller_goal_id);
    ASSERT_TRUE(unfenced_dispatch.ok() && unfenced_dispatch.value().accepted);
    backend.refuse_local_fence = true;
    const auto local_refusal = unfenced.TranslateStopStage(executed.value(), budget, {});
    EXPECT_EQ(local_refusal.attempt_disposition, StopStageAttemptDispositionDTO::kDispatched);
    EXPECT_EQ(local_refusal.outcome, ParticipantStopStageOutcomeDTO::kFailed);
    ASSERT_TRUE(local_refusal.error);
    EXPECT_EQ(local_refusal.error->details.at("reason"), "gripper_stop_generation_unavailable");
    EXPECT_FALSE(local_refusal.controller_acknowledgement_sequence);
    ASSERT_EQ(local_refusal.evidence_items.size(), 1U);
    EXPECT_EQ(local_refusal.evidence_items.front().state, StopEvidenceItemStateDTO::kMissing);
    EXPECT_FALSE(local_refusal.evidence_items.front().evidence);
    EXPECT_EQ(backend.invalidations.load(), 3);
  }
}

// The gripper Stop translation releases the session mutex across the backend
// invalidation (the ROS cancel request): the kernel's concurrent fence on the
// same session completes while that invalidation is blocked.
TEST(ResourceAddressedExecutionKernelTest, GripperStopTranslationDoesNotHoldSessionAcrossInvalidate) {
  class Backend final : public IGripperCommandBackend {
   public:
    mutable std::mutex mutex;
    GripperCommandStatusDTO status;
    std::function<void()> invalidate_hook;
    std::atomic<int> invalidations{};
    GripperCommandResultDTO command_gripper(const GripperCommandRequestDTO& request) override {
      std::lock_guard lock(mutex);
      status.gripper_id = request.gripper_id;
      status.command_id = 41U;
      status.generation = 73U;
      status.state = GripperCommandState::kExecuting;
      ++status.revision;
      return {true, 41U, 73U, std::nullopt};
    }
    GripperCommandStatusDTO get_gripper_status(const std::string&) const override {
      std::lock_guard lock(mutex);
      return status;
    }
    GripperCommandResultDTO mark_gripper_grasp_lost(const std::string&, std::uint64_t,
                                                    std::uint64_t, const std::string&,
                                                    const std::string&,
                                                    const std::string&) override {
      return {};
    }
    void invalidate_gripper_commands(GripperInvalidationReason) noexcept override {
      if (invalidate_hook) invalidate_hook();
      std::lock_guard lock(mutex);
      status.state = GripperCommandState::kIdle;
      ++status.generation;
      ++status.revision;
      ++invalidations;
    }
    void authorize_gripper_commands() noexcept override {}
  } backend;
  FakeClock clock;
  ManualScheduler scheduler;
  GripperParticipantEngine gripper(backend, clock);
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  auto row = LogicalGripperRegistration(make_binding("gripper.target", "tool.gripper.command",
                                                      CoordinateKind::kLinear, schema), gripper);
  auto kernel_heap_test_owner = make_claimed_kernel(
      {row}, clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;
  auto executing =
      std::async(std::launch::async, [&] { return kernel.execute(command_operation()); });
  ASSERT_EQ(executing.wait_for(std::chrono::seconds(2)), std::future_status::ready);
  const auto accepted = executing.get();
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;

  HeldSettlementCall invalidate;
  backend.invalidate_hook = invalidate.Blocker();
  const auto stopped =
      kernel.cell_stop(FullStopIntentDTO{{TestRequestKey("gripper.unlocked.stop"), "test"}, {}});
  ASSERT_EQ(stopped.covered.size(), 1U);
  ASSERT_TRUE(invalidate.Entered());

  // Stop translation is now inside invalidate_gripper_commands.
  auto fence = std::async(std::launch::async,
                          [&] { return gripper.fence_addressed_participant_stop(1U); });
  const bool fenced_while_blocked =
      fence.wait_for(std::chrono::seconds(2)) == std::future_status::ready;
  const bool observed_while_blocked = gripper.ObservePreparedCapabilityCommand(1U).ok();
  invalidate.Release();
  EXPECT_TRUE(fenced_while_blocked);
  EXPECT_TRUE(observed_while_blocked);
  EXPECT_EQ(fence.get().disposition, AddressedParticipantStopFenceDisposition::kDispatchCommitted);

  ASSERT_TRUE(wait_until(
      [&] {
        const auto status = kernel.read_stop(stopped.event_id);
        return status.ok() && status.value().complete;
      },
      std::chrono::seconds(2)));
  const auto stop_readback = kernel.read_stop(stopped.event_id);
  ASSERT_TRUE(stop_readback.ok());
  EXPECT_EQ(stop_readback.value().result, StopEventResult::kStopped);
  // Physical containment plus the local settlement's invalidation, and no
  // more.
  ASSERT_TRUE(wait_until([&] { return backend.invalidations.load() == 2; },
                         std::chrono::seconds(5)))
      << backend.invalidations.load();
  // Dropped with the per-stage evidence: replaying the recorded translation
  // of the same stage returns the identical result without a second
  // invalidation.
  EXPECT_EQ(backend.invalidations.load(), 2);
}

// OD-67 / audit 3.7-3.8: Execute holds submission ordering only through
// admission. While a gripper dispatch is blocked inside command_gripper (the
// ROS publish or goal send), the speed control and another admission complete;
// the setting written meanwhile seeds that admission, and replays stay exact.
TEST(ResourceAddressedExecutionKernelTest, BlockedGripperDispatchDoesNotHoldSubmissionOrdering) {
  class Backend final : public IGripperCommandBackend {
   public:
    mutable std::mutex mutex;
    GripperCommandStatusDTO status;
    std::function<void()> command_hook;
    std::atomic<int> commands{};
    GripperCommandResultDTO command_gripper(const GripperCommandRequestDTO& request) override {
      if (command_hook) command_hook();
      std::lock_guard lock(mutex);
      ++commands;
      status.gripper_id = request.gripper_id;
      status.command_id = 41U;
      status.generation = 73U;
      status.state = GripperCommandState::kExecuting;
      ++status.revision;
      return {true, 41U, 73U, std::nullopt};
    }
    GripperCommandStatusDTO get_gripper_status(const std::string&) const override {
      std::lock_guard lock(mutex);
      return status;
    }
    GripperCommandResultDTO mark_gripper_grasp_lost(const std::string&, std::uint64_t,
                                                    std::uint64_t, const std::string&,
                                                    const std::string&,
                                                    const std::string&) override {
      return {};
    }
    void invalidate_gripper_commands(GripperInvalidationReason) noexcept override {
      std::lock_guard lock(mutex);
      status.state = GripperCommandState::kIdle;
      ++status.generation;
      ++status.revision;
    }
    void authorize_gripper_commands() noexcept override {}
  } backend;
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine arm;
  GripperParticipantEngine gripper(backend, clock);
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  auto kernel_heap_test_owner = make_claimed_kernel(
      {registration(make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
                    arm),
       LogicalGripperRegistration(make_binding("gripper.target", "tool.gripper.command",
                                               CoordinateKind::kLinear, schema),
                                  gripper)},
      clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;

  HeldSettlementCall dispatch;
  backend.command_hook = dispatch.Blocker();
  const auto command_intent = command_operation("request.blocked.command");
  auto commanding = std::async(std::launch::async, [&] { return kernel.execute(command_intent); });
  ASSERT_TRUE(dispatch.Entered());

  const auto scale_request = runtime_scale_control_request("request.blocked.scale", 0U, 0.4);
  auto scaling = std::async(std::launch::async,
                            [&] { return kernel.set_runtime_scale_control(scale_request); });
  const bool scaled_while_blocked =
      scaling.wait_for(std::chrono::seconds(2)) == std::future_status::ready;
  auto moving = std::async(std::launch::async,
                           [&] { return kernel.execute(motion_operation("request.blocked.motion")); });
  const bool admitted_while_blocked =
      moving.wait_for(std::chrono::seconds(2)) == std::future_status::ready;
  dispatch.Release();
  EXPECT_TRUE(scaled_while_blocked);
  EXPECT_TRUE(admitted_while_blocked);

  const auto commanded = commanding.get();
  ASSERT_TRUE(commanded.ok()) << commanded.error().message;
  const auto scaled = scaling.get();
  ASSERT_TRUE(scaled.ok()) << scaled.error().message;
  EXPECT_EQ(scaled.value().control_generation, RuntimeScaleControlGeneration(1U));
  const auto moved = moving.get();
  ASSERT_TRUE(moved.ok()) << moved.error().message;
  EXPECT_NE(moved.value().operation_id, commanded.value().operation_id);
  // The setting recorded before the motion's admission seeds that motion.
  ASSERT_TRUE(arm.last_execute.has_value());
  ASSERT_TRUE(arm.last_execute->initial_runtime_scale.has_value());
  EXPECT_DOUBLE_EQ(arm.last_execute->initial_runtime_scale->requested_scale, 0.4);
  EXPECT_EQ(backend.commands.load(), 1);

  // Replays after the interleaving return the original decisions, with no
  // second provider command.
  const auto command_replay = kernel.execute(command_intent);
  ASSERT_TRUE(command_replay.ok()) << command_replay.error().message;
  EXPECT_EQ(command_replay.value().replay_status, RequestReplayStatusDTO::kReplayedExact);
  EXPECT_EQ(command_replay.value().operation_id, commanded.value().operation_id);
  const auto scale_replay = kernel.set_runtime_scale_control(scale_request);
  ASSERT_TRUE(scale_replay.ok()) << scale_replay.error().message;
  EXPECT_EQ(scale_replay.value().replay_status, RequestReplayStatusDTO::kReplayedExact);
  EXPECT_EQ(scale_replay.value().control_generation, scaled.value().control_generation);
  EXPECT_EQ(backend.commands.load(), 1);
}

// A ROS action gripper whose cancel terminal arrives after the Stop.
// Admission closes on every invalidation and reopens only through
// try_authorize once that terminal has arrived (b9c5798c).
class CancelTerminalGripperBackend final : public IGripperCommandBackend {
 public:
  mutable std::mutex mutex;
  GripperCommandStatusDTO status;
  bool admission_open{true};
  std::atomic<int> commands{};
  std::atomic<int> refused{};
  std::atomic<int> opens{};
  std::atomic<bool> cancel_unsettled{true};
  GripperCommandResultDTO command_gripper(const GripperCommandRequestDTO& request) override {
    std::lock_guard lock(mutex);
    if (!admission_open) {
      ++refused;
      return {false, 0U, 0U,
              ErrorDTO{"gripper_command_not_authorized",
                       "Gripper command admission is closed by the execution lifecycle", {}}};
    }
    ++commands;
    status.gripper_id = request.gripper_id;
    status.command_id = 40U + static_cast<std::uint64_t>(commands.load());
    status.generation += 10U;
    status.state = GripperCommandState::kExecuting;
    ++status.revision;
    return {true, status.command_id, status.generation, std::nullopt};
  }
  GripperCommandStatusDTO get_gripper_status(const std::string&) const override {
    std::lock_guard lock(mutex);
    auto copy = status;
    // The controller's terminal for the Stop's cancel has not arrived.
    copy.cancellation_pending = !admission_open && cancel_unsettled;
    return copy;
  }
  GripperCommandResultDTO mark_gripper_grasp_lost(const std::string&, std::uint64_t,
                                                  std::uint64_t, const std::string&,
                                                  const std::string&,
                                                  const std::string&) override {
    return {};
  }
  void invalidate_gripper_commands(GripperInvalidationReason) noexcept override {
    std::lock_guard lock(mutex);
    admission_open = false;
    status.state = GripperCommandState::kIdle;
    ++status.generation;
    ++status.revision;
  }
  void authorize_gripper_commands() noexcept override {
    std::lock_guard lock(mutex);
    admission_open = true;
    ++opens;
  }
  Result<void> try_authorize_gripper_commands() noexcept override {
    if (cancel_unsettled)
      return Result<void>::Err(ErrorDTO{"gripper_cancellation_unsettled",
                                        "The prior gripper cancellation remains unsettled", {}});
    authorize_gripper_commands();
    return Result<void>::Ok();
  }
};

TEST(ResourceAddressedExecutionKernelTest, GripperFullStopSettlesBeforeItsCancelTerminalArrives) {
  CancelTerminalGripperBackend backend;
  FakeClock clock;
  ManualScheduler scheduler;
  GripperParticipantEngine gripper(backend, clock);
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  auto row = LogicalGripperRegistration(make_binding("gripper.target", "tool.gripper.command",
                                                      CoordinateKind::kLinear, schema), gripper);
  auto kernel_heap_test_owner = make_claimed_kernel(
      {row}, clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;
  const auto accepted = kernel.execute(command_operation());
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  const auto stopped =
      kernel.stop_all(FullStopIntentDTO{{TestRequestKey("cancel-pending.stop"), "test"}, {}});
  ASSERT_TRUE(wait_until(
      [&] {
        const auto status = kernel.read_stop(stopped.event_id);
        return status.ok() && status.value().complete;
      },
      std::chrono::seconds(1)));
  const auto status = kernel.read_stop(stopped.event_id);
  ASSERT_TRUE(status.ok());
  EXPECT_EQ(status.value().result, StopEventResult::kStopped);  // contained, none failed
  ASSERT_TRUE(wait_until([&] {
    const auto state = kernel.get_operation_state(accepted.value().operation_id);
    return state.ok() && state.value().state == OperationStateKind::kStopped;
  }));
  EXPECT_EQ(backend.opens.load(), 0);  // admission not reopened before the terminal

  // Cycle Reset: the operation Reset reaches reset_gripper and reopens once
  // the terminal has arrived.
  backend.cancel_unsettled = false;
  const auto before_reset = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(before_reset.ok());
  const auto reset = kernel.reset(control_request("cancel-pending.reset", accepted.value(),
                                                  before_reset.value().operation_revision.value()));
  ASSERT_TRUE(reset.ok()) << reset.error().message;
  ASSERT_TRUE(wait_until([&] { return backend.opens.load() == 1; }));
}

TEST(ResourceAddressedExecutionKernelTest,
     ManualGripperStopRetiresOnlyAfterTheControllerCancelTerminal) {
  // The Stop settles before the controller reports the cancelled goal.
  // The automatic manual retirement (Reset) waits for that terminal instead
  // of failing into InterventionRequired.
  CancelTerminalGripperBackend backend;
  FakeClock clock;
  ManualScheduler scheduler;
  GripperParticipantEngine gripper(backend, clock);
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  auto direct = LogicalGripperRegistration(make_binding("gripper.target",
                                                        "tool.gripper.command",
                                                        CoordinateKind::kLinear, schema),
                                           gripper);
  direct.intrinsic_direct_control = true;
  ResourceAddressedExecutionKernelConfig config{kTestApplicationStartId,
                                                CellId("cell.test"), 8U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  // Manual-only work: no Program claim (a held Program claim refuses a
  // manual claim that is not a handover).
  auto kernel_heap_test_owner = make_unclaimed_kernel({direct}, clock, scheduler, default_journal, config);
  auto& kernel = *kernel_heap_test_owner;
  ASSERT_TRUE(ready_cell_admission(kernel).ok());
  auto manual = command_operation("manual.cancel.command");
  manual.program_run_id.reset();
  manual.participants.front().execution_scope.reset();  // manual work: no run, no scope
  const auto accepted = kernel.execute(manual);
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  ASSERT_TRUE(wait_until([&] { return backend.commands.load() == 1; }));
  const auto before_stop = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(before_stop.ok());
  const auto stopped = kernel.stop(stop_request("manual.cancel.stop", accepted.value(),
                                                before_stop.value().operation_revision.value()));
  ASSERT_EQ(stopped.widen_reason, StopWidenReason::kNone);
  ASSERT_TRUE(wait_until([&] {
    const auto state = kernel.get_operation_state(accepted.value().operation_id);
    return state.ok() && state.value().state == OperationStateKind::kStopped;
  }));

  // Before the terminal: no Reset is sent; the operation stays Stopped.
  for (int round = 0; round < 3; ++round)
    ASSERT_TRUE(kernel.reconcile_manual_operation_admission().ok());
  const auto waiting = kernel.get_operation_projection(accepted.value().operation_id);
  ASSERT_TRUE(waiting.ok());
  EXPECT_TRUE(waiting.value().resident);
  EXPECT_EQ(kernel.get_operation_state(accepted.value().operation_id).value().state,
            OperationStateKind::kStopped);
  EXPECT_EQ(backend.opens.load(), 0);

  // The controller reports the cancelled goal: retirement resets and reopens.
  backend.cancel_unsettled = false;
  ASSERT_TRUE(wait_until([&] {
    if (!kernel.reconcile_manual_operation_admission().ok()) return false;
    const auto projection = kernel.get_operation_projection(accepted.value().operation_id);
    return projection.ok() && !projection.value().resident;
  }));
  EXPECT_EQ(backend.opens.load(), 1);
}

TEST(ResourceAddressedExecutionKernelTest, GripperStopResumeReopensAdmissionAfterCancelTerminal) {
  CancelTerminalGripperBackend backend;
  FakeClock clock;
  ManualScheduler scheduler;
  GripperParticipantEngine gripper(backend, clock);
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  auto row = LogicalGripperRegistration(make_binding("gripper.target", "tool.gripper.command",
                                                      CoordinateKind::kLinear, schema), gripper);
  auto kernel_heap_test_owner = make_claimed_kernel(
      {row}, clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;
  const auto accepted = kernel.execute(command_operation());
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  const auto before_stop = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(before_stop.ok());
  const auto stopped = kernel.stop(stop_request("resume.stop", accepted.value(),
                                                before_stop.value().operation_revision.value()));
  ASSERT_TRUE(wait_until([&] {
    const auto stop = kernel.read_stop(stopped.event_id);
    return stop.ok() && stop.value().complete;
  }));
  EXPECT_EQ(kernel.read_stop(stopped.event_id).value().result, StopEventResult::kStopped);
  ASSERT_TRUE(wait_until([&] {
    const auto state = kernel.get_operation_state(accepted.value().operation_id);
    return state.ok() && state.value().state == OperationStateKind::kStopped;
  }));
  const auto resume = [&](const std::string& request_id) {
    const auto projection = kernel.get_operation_recovery_assessment(accepted.value().operation_id);
    EXPECT_TRUE(projection.ok());
    const auto& assessment = projection.value().assessment;
    KernelRecoveryActionRequestDTO request{TestRequestKey(request_id),
                                           RecoveryAction::kReplanFromStoppedState,
                                           "operator",
                                           assessment.assessment_revision,
                                           assessment.control_command_epoch,
                                           assessment.execution_id,
                                           "resume stopped node",
                                           false};
    return kernel.apply_operation_recovery_action(accepted.value().operation_id,
                                                  projection.value().operation_revision, request);
  };

  // Resume before the cancel terminal refuses cleanly with the typed reason.
  const auto early = resume("resume.early");
  ASSERT_TRUE(early.ok()) << early.error().message;
  EXPECT_FALSE(early.value().accepted);
  ASSERT_TRUE(early.value().error);
  EXPECT_EQ(early.value().error->code, "gripper_cancellation_unsettled");
  EXPECT_EQ(backend.opens.load(), 0);

  // After the terminal, Resume reopens admission and the next command is sent.
  backend.cancel_unsettled = false;
  const auto resumed = resume("resume.after-terminal");
  ASSERT_TRUE(resumed.ok()) << resumed.error().message;
  EXPECT_TRUE(resumed.value().accepted);
  EXPECT_EQ(backend.opens.load(), 1);
  const auto next = kernel.execute(command_operation("request.command.2"));
  ASSERT_TRUE(next.ok()) << next.error().message;
  ASSERT_TRUE(wait_until([&] { return backend.commands.load() == 2; }));
  EXPECT_EQ(backend.refused.load(), 0);
}

TEST(ResourceAddressedExecutionKernelTest, GripperStopFencesTheActualReleasedButUnenteredDispatch) {
  for (const auto actuation : {GripperActuationKind::kPositionCommanded}) {
    SCOPED_TRACE(static_cast<int>(actuation));
    class Backend final : public IGripperCommandBackend {
     public:
      GripperActuationKind actuation{GripperActuationKind::kPositionCommanded};
      GripperActuationKind gripper_actuation_kind(const std::string&) const override { return actuation; }
      int commands{};
      int invalidations{};
      GripperCommandResultDTO command_gripper(const GripperCommandRequestDTO&) override {
        ++commands;
        return {true, 41U, 73U, {}};
      }
      GripperCommandStatusDTO get_gripper_status(const std::string& id) const override {
        GripperCommandStatusDTO value;
        value.gripper_id = id;
        return value;
      }
      GripperCommandResultDTO mark_gripper_grasp_lost(const std::string&, std::uint64_t,
          std::uint64_t, const std::string&, const std::string&, const std::string&) override { return {}; }
      void invalidate_gripper_commands(GripperInvalidationReason) noexcept override { ++invalidations; }
      void authorize_gripper_commands() noexcept override {}
    } backend;
    backend.actuation = actuation;
    FakeClock clock;
    ManualScheduler scheduler;
    FakeOperationJournal journal;
    GripperParticipantEngine gripper(backend, clock);
    HeldSettlementCall before_entry;
    PreparedGripperForwarder forwarder(gripper, before_entry.Blocker());
    const ProgramCommandSchemaRefDTO schema{
        CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
        CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
    auto row = LogicalGripperRegistration(make_binding("gripper.target", "tool.gripper.command",
                                                        CoordinateKind::kLinear, schema), gripper);
    row.prepared_motion_engine = &forwarder;
    auto kernel_heap_test_owner = make_claimed_kernel({row}, clock, scheduler, journal,
        {kTestApplicationStartId, CellId("cell.test"), 8U});
    auto& kernel = *kernel_heap_test_owner;
    auto executing = std::async(std::launch::async, [&] { return kernel.execute(command_operation()); });
    const bool entered = before_entry.Entered();
    if (!entered) before_entry.Release();
    ASSERT_TRUE(entered);
    EXPECT_EQ(gripper.ObservePreparedCapabilityCommand(1U).value().state,
              ResolvedPreparedCapabilityCommandStateDTO::kPrepared);
    const auto stopped = kernel.stop_all(
        FullStopIntentDTO{{TestRequestKey("stop.real-gripper-entry-gap"), "test"}, {}});
    const bool certified = wait_until([&] {
      auto status = kernel.read_stop(stopped.event_id);
      return status.ok() && status.value().complete;
    });
    if (!certified) before_entry.Release();
    ASSERT_TRUE(certified);
    EXPECT_EQ(gripper.ObservePreparedCapabilityCommand(1U).value().state,
              ResolvedPreparedCapabilityCommandStateDTO::kCancelledPreDispatch);
    EXPECT_EQ(backend.commands, 0);
    EXPECT_EQ(backend.invalidations, 0);
    EXPECT_FALSE(kernel.get_cell_latch().latched);
    before_entry.Release();
    const auto returned = executing.get();
    EXPECT_EQ(backend.commands, 0);
    EXPECT_EQ(backend.invalidations, 0);
    const auto status = kernel.read_stop(stopped.event_id);
    ASSERT_TRUE(status.ok());
    ASSERT_TRUE(status.value().complete);
    // No Stop stage ran: nothing contained it by a stage.
    ASSERT_EQ(status.value().covered.size(), 1U);
    EXPECT_FALSE(status.value().covered.front().containing_stage_index.has_value());
    const auto session = gripper.ObservePreparedCapabilityCommand(1U);
    ASSERT_TRUE(session.ok());
    EXPECT_FALSE(session.value().dispatch_result);
    EXPECT_EQ(session.value().state, ResolvedPreparedCapabilityCommandStateDTO::kCancelledPreDispatch);
    EXPECT_EQ(gripper.get_recovery_assessment().source_id, "addressed_participant_cancelled_before_dispatch");
    ASSERT_EQ(stopped.covered.size(), 1U);
    const auto terminal = kernel.get_operation_state(stopped.covered.front().operation_id);
    ASSERT_TRUE(terminal.ok());
    EXPECT_EQ(terminal.value().state, OperationStateKind::kStopped);
    (void)returned;  // The exact Stop owns the terminal, not the rejected late Dispatch return.
  }

}

TEST(ResourceAddressedExecutionKernelTest,
     HeldPreparedJournalWriteCannotReleaseASecondPreparationAdvance) {
  for (const bool command : {false, true}) {
    SCOPED_TRACE(command);
    FakeClock clock;
    ManualScheduler scheduler;
    FakeParticipantEngine engine;
    FakeOperationJournal journal;
    const ProgramCommandSchemaRefDTO schema{
        CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
        CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
    const auto binding = command ? make_binding("gripper.target", "tool.gripper.command",
                                                CoordinateKind::kLinear, schema)
                                 : make_binding("arm", "execution.trajectory.execute",
                                                CoordinateKind::kAngular);
    auto kernel_heap_test_owner = make_claimed_kernel(
        {registration(binding, engine)}, clock, scheduler, journal,
        {kTestApplicationStartId, CellId("cell.test"), 8U});
    auto& kernel = *kernel_heap_test_owner;
    // The prepared state is applied in the section that posts its row: with
    // the disk stalled, an observation never sees a second advance to release.
    StalledJournal stalled(journal);
    const auto admitted = kernel.execute(command ? command_operation() : motion_operation());
    ASSERT_TRUE(admitted.ok()) << admitted.error().message;
    const auto observed = kernel.reconcile_subordinate_state();
    EXPECT_TRUE(observed.ok()) << observed.error().message;
    stalled.Release();
    ASSERT_TRUE(drain_journal(kernel));
    EXPECT_EQ(engine.cancel_prepared_motion_calls.load(), 0);
    EXPECT_EQ(engine.cancel_prepared_command_calls.load(), 0);
    EXPECT_EQ(engine.dispatch_prepared_motion_calls.load(), command ? 0 : 1);
    EXPECT_EQ(engine.dispatch_prepared_command_calls.load(), command ? 1 : 0);
  }
}

TEST(ResourceAddressedExecutionKernelTest,
     CommandReturnSettlesStopWhileSiblingJournalWriteRemainsHeld) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine motion_engine, command_engine;
  FakeOperationJournal journal;
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  const auto motion =
      make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular);
  const auto command =
      coordinated_occurrence(make_binding("gripper.target", "tool.gripper.command",
                                          CoordinateKind::kLinear, schema),
                             "2");
  auto kernel_heap_test_owner = make_unclaimed_kernel(
      {registration(motion, motion_engine), registration(command, command_engine)}, clock,
      scheduler, journal, {kTestApplicationStartId, CellId("cell.test"), 16U});
  auto& kernel = *kernel_heap_test_owner;
  HeldSettlementCall dispatch_return;
  command_engine.dispatch_prepared_command_hook = dispatch_return.Blocker();
  // The sibling's observation row stays unwritten on a stalled disk.
  StalledJournal stalled(journal);
  auto executing = std::async(std::launch::async, [&] {
    return kernel.execute(coordinated_motion_command_operation("command.held-sibling"));
  });
  ASSERT_TRUE(dispatch_return.Entered());
  auto observing = std::async(std::launch::async, [&] {
    motion_engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
  });
  // The observation returns at once; its row waits on the stalled disk.
  EXPECT_EQ(observing.wait_for(std::chrono::seconds(10)), std::future_status::ready);
  const auto stopped =
      kernel.stop_all(FullStopIntentDTO{{TestRequestKey("stop.held-sibling"), "test"}, {}});
  // Both participants are contained by an authoritative, error-free stage.
  EXPECT_TRUE(wait_until(
      [&] {
        const auto status = kernel.read_stop(stopped.event_id);
        return status.ok() &&
               std::count_if(status.value().covered.begin(), status.value().covered.end(),
                             [](const auto& entry) {
                               return entry.done && entry.phase == StopPhase::kStopped &&
                                      entry.containing_stage_index.has_value() &&
                                      !entry.error_code.has_value();
                             }) == 2;
      },
      std::chrono::seconds(1)));
  dispatch_return.Release();
  const bool settled_before_write = wait_until(
      [&] {
        const auto status = kernel.read_stop(stopped.event_id);
        return status.ok() && status.value().complete;
      },
      std::chrono::seconds(1));
  EXPECT_TRUE(settled_before_write);
  observing.get();
  stalled.Release();
  ASSERT_TRUE(drain_journal(kernel));
  const auto admitted = executing.get();
  ASSERT_TRUE(admitted.ok()) << admitted.error().message;
  EXPECT_EQ(kernel.get_operation_state(admitted.value().operation_id).value().state,
            OperationStateKind::kStopped);
  EXPECT_EQ(command_engine.participant_stop_settlement_calls.load(), 1);
  EXPECT_EQ(command_engine.cancel_prepared_command_calls.load(), 0);
}

TEST(ResourceAddressedExecutionKernelTest,
     LinearGripperCommandUsesResolvedTargetAndReconcilesCompletion) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  auto kernel_heap_test_owner = make_claimed_kernel(
      {registration(make_binding("gripper.target", "tool.gripper.command",
                                 CoordinateKind::kLinear, schema),
                    engine)},
      clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;

  const auto accepted = kernel.execute(command_operation());
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  ASSERT_TRUE(engine.last_command.has_value());
  EXPECT_EQ(engine.last_command->gripper_id, "gripper.target");
  EXPECT_EQ(engine.last_command->group_id, "mf2_gripper_group");
  EXPECT_EQ(engine.last_command->joint_name, "mf2_finger_joint");
  EXPECT_DOUBLE_EQ(engine.last_command->target_position, 0.02);
  ASSERT_TRUE(engine.last_command->max_effort.has_value());
  EXPECT_DOUBLE_EQ(*engine.last_command->max_effort, 8.0);
  EXPECT_DOUBLE_EQ(engine.last_command->duration_s, 0.5);
  EXPECT_DOUBLE_EQ(engine.last_command->completion_timeout_s, 2.0);
  EXPECT_EQ(engine.validate_command_calls, 2);
  EXPECT_EQ(engine.prepare_command_calls, 1);
  EXPECT_EQ(engine.dispatch_prepared_command_calls, 1);
  ASSERT_TRUE(engine.prepared_command_snapshot.has_value());
  ASSERT_TRUE(engine.prepared_command_snapshot->participant);
  EXPECT_TRUE(std::holds_alternative<PreparedCapabilityCommandDTO>(
      engine.prepared_command_snapshot->participant->payload));
  EXPECT_EQ(kernel.resource_snapshot().front().state, ResourceSlotState::kDispatched);

  const auto replay = kernel.execute(command_operation());
  ASSERT_TRUE(replay.ok()) << replay.error().message;
  EXPECT_EQ(replay.value().replay_status, RequestReplayStatusDTO::kReplayedExact);
  EXPECT_EQ(engine.prepare_command_calls, 1);
  EXPECT_EQ(engine.dispatch_prepared_command_calls, 1);
  EXPECT_EQ(engine.command_calls, 1);

  engine.gripper_status.state = GripperCommandState::kCompleted;
  engine.gripper_status.progress = 1.0;
  const auto reconciled = kernel.reconcile_subordinate_state();
  ASSERT_TRUE(reconciled.ok()) << reconciled.error().message;
  EXPECT_EQ(kernel.resource_snapshot().front().state, ResourceSlotState::kTerminal);
  const auto state = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(state.ok());
  EXPECT_EQ(state.value().state, OperationStateKind::kCompleted);
}

TEST(ResourceAddressedExecutionKernelTest, GripperCommandCarriesWaitForDurationOption) {
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  const auto with_options = [](std::vector<CommandOptionDTO> options) {
    auto operation = command_operation();
    std::get<CapabilityCommandIntentDTO>(operation.participants.front().payload).caller_options =
        std::move(options);
    return operation;
  };
  {
    FakeClock clock;
    ManualScheduler scheduler;
    FakeParticipantEngine engine;
    auto kernel_heap_test_owner = make_claimed_kernel(
        {registration(make_binding("gripper.target", "tool.gripper.command",
                                   CoordinateKind::kLinear, schema),
                      engine)},
        clock, scheduler, default_journal,
        {kTestApplicationStartId, CellId("cell.test"), 8U});
    auto& kernel = *kernel_heap_test_owner;
    const auto accepted = kernel.execute(
        with_options({CommandOptionDTO{CommandOptionId("wait_for_duration"), true},
                      CommandOptionDTO{CommandOptionId("command_duration_s"), 0.5}}));
    ASSERT_TRUE(accepted.ok()) << accepted.error().message;
    ASSERT_TRUE(engine.last_command.has_value());
    EXPECT_DOUBLE_EQ(engine.last_command->duration_s, 0.5);
    EXPECT_TRUE(engine.last_command->wait_for_duration);
  }
  {
    FakeClock clock;
    ManualScheduler scheduler;
    FakeParticipantEngine engine;
    auto kernel_heap_test_owner = make_claimed_kernel(
        {registration(make_binding("gripper.target", "tool.gripper.command",
                                   CoordinateKind::kLinear, schema),
                      engine)},
        clock, scheduler, default_journal,
        {kTestApplicationStartId, CellId("cell.test"), 8U});
    auto& kernel = *kernel_heap_test_owner;
    const auto accepted = kernel.execute(command_operation());
    ASSERT_TRUE(accepted.ok()) << accepted.error().message;
    ASSERT_TRUE(engine.last_command.has_value());
    EXPECT_FALSE(engine.last_command->wait_for_duration);
  }
  {
    // The flag is a bool option; a duration value under its id is refused.
    FakeClock clock;
    ManualScheduler scheduler;
    FakeParticipantEngine engine;
    auto kernel_heap_test_owner = make_claimed_kernel(
        {registration(make_binding("gripper.target", "tool.gripper.command",
                                   CoordinateKind::kLinear, schema),
                      engine)},
        clock, scheduler, default_journal,
        {kTestApplicationStartId, CellId("cell.test"), 8U});
    auto& kernel = *kernel_heap_test_owner;
    const auto rejected =
        kernel.execute(with_options({CommandOptionDTO{CommandOptionId("wait_for_duration"), 1.0}}));
    ASSERT_FALSE(rejected.ok());
    EXPECT_EQ(rejected.error().details.at("reason"), "command_option_unsupported");
    EXPECT_FALSE(engine.last_command.has_value());
  }
}

TEST(ResourceAddressedExecutionKernelTest,
     ReconciliationSkipsCapabilityCommandWhilePreparedDispatchEffectIsInFlight) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  engine.gripper_status.state = GripperCommandState::kIdle;
  std::promise<void> dispatch_entered;
  std::promise<void> release_dispatch;
  const auto release_future = release_dispatch.get_future().share();
  engine.dispatch_prepared_command_hook = [&] {
    dispatch_entered.set_value();
    release_future.wait();
  };
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  auto kernel_heap_test_owner = make_claimed_kernel(
      {registration(make_binding("gripper.target", "tool.gripper.command",
                                 CoordinateKind::kLinear, schema),
                    engine)},
      clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;

  auto executing =
      std::async(std::launch::async, [&] { return kernel.execute(command_operation()); });
  ASSERT_EQ(dispatch_entered.get_future().wait_for(std::chrono::seconds(10)),
            std::future_status::ready);
  const OperationNumber operation_id(1U);  // the Kernel's first operation
  const auto before_reconciliation = kernel.get_operation_state(operation_id);
  ASSERT_TRUE(before_reconciliation.ok()) << before_reconciliation.error().message;
  const auto status_polls_before = engine.get_gripper_status_calls.load();

  const auto reconciled_while_dispatching = kernel.reconcile_subordinate_state();
  ASSERT_TRUE(reconciled_while_dispatching.ok()) << reconciled_while_dispatching.error().message;
  EXPECT_EQ(engine.get_gripper_status_calls.load(), status_polls_before);
  const auto unchanged = kernel.get_operation_state(operation_id);
  ASSERT_TRUE(unchanged.ok()) << unchanged.error().message;
  EXPECT_EQ(unchanged.value(), before_reconciliation.value());

  release_dispatch.set_value();
  const auto accepted = executing.get();
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  EXPECT_EQ(accepted.value().operation_id, operation_id);
  engine.gripper_status.state = GripperCommandState::kCompleted;
  engine.gripper_status.command_id = engine.next_command_result.command_id;
  engine.gripper_status.generation = engine.next_command_result.generation;
  engine.gripper_status.progress = 1.0;

  const auto reconciled_completion = kernel.reconcile_subordinate_state();
  ASSERT_TRUE(reconciled_completion.ok()) << reconciled_completion.error().message;
  EXPECT_EQ(engine.get_gripper_status_calls.load(), status_polls_before + 1);
  const auto completed = kernel.get_operation_state(operation_id);
  ASSERT_TRUE(completed.ok()) << completed.error().message;
  EXPECT_EQ(completed.value().state, OperationStateKind::kCompleted);
  EXPECT_EQ(completed.value().participants.front().state, OperationStateKind::kCompleted);
}

TEST(ResourceAddressedExecutionKernelTest,
     StopDuringCapabilityCommandPrepareCancelsWithoutDispatchOrStopStage) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  std::promise<void> prepare_entered;
  std::promise<void> release_prepare;
  auto release_future = release_prepare.get_future().share();
  engine.prepare_command_hook = [&] {
    prepare_entered.set_value();
    release_future.wait();
  };
  auto kernel_heap_test_owner = make_claimed_kernel(
      {registration(make_binding("gripper.target", "tool.gripper.command",
                                 CoordinateKind::kLinear, schema),
                    engine)},
      clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;

  auto executing =
      std::async(std::launch::async, [&] { return kernel.execute(command_operation()); });
  ASSERT_EQ(prepare_entered.get_future().wait_for(std::chrono::seconds(10)),
            std::future_status::ready);
  const OperationAcceptedDTO expected{TestRequestKey("request.command.1"),
                                      RequestReplayStatusDTO::kAcceptedNew,
                                      OperationNumber(1U),
                                      OperationRevision(1U),
                                      {},
                                      0};
  const auto stopped = kernel.stop(stop_request("request.command.prepare.stop", expected, 1U));
  release_prepare.set_value();
  const auto accepted = executing.get();
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  ASSERT_TRUE(wait_until([&] { return engine.cancel_prepared_command_calls.load() > 0; }));
  EXPECT_EQ(engine.cancel_prepared_command_calls.load(), 1);
  EXPECT_EQ(engine.dispatch_prepared_command_calls, 0);
  EXPECT_EQ(engine.command_calls, 0);
  EXPECT_EQ(engine.translate_stop_stage_calls.load(), 0);
  ASSERT_TRUE(wait_until([&] {
    const auto status = kernel.read_stop(stopped.event_id);
    return status.ok() && status.value().complete;
  }));
  const auto status = kernel.read_stop(stopped.event_id);
  ASSERT_TRUE(status.ok()) << status.error().message;
  EXPECT_EQ(status.value().result, StopEventResult::kStopped);
  // Never dispatched: cancelled before dispatch, no Stop stage ran.
  ASSERT_EQ(status.value().covered.size(), 1U);
  EXPECT_FALSE(status.value().covered.front().containing_stage_index.has_value());
  EXPECT_EQ(status.value().covered.front().phase, StopPhase::kStopped);
  // As released, the Stop path writes an execution fact only for motion
  // participants; this capability command ends Stopped without one.
  const auto state = kernel.get_operation_state(accepted.value().operation_id).value();
  EXPECT_EQ(state.state, OperationStateKind::kStopped);
  EXPECT_EQ(state.participants.front().state, OperationStateKind::kStopped);
  EXPECT_FALSE(state.participants.front().terminal_fact.has_value());
}

TEST(ResourceAddressedExecutionKernelTest,
     StopWaitingOnCommandPreparationIsWokenWhenThePreparationBorrowEnds) {
  // A Stop accepted during the Prepare call has no product to cancel yet; it
  // waits for that call and the following prepared read to end. Ending the
  // last borrow is that Stop's only remaining wakeup: here the read fails, so
  // no dispatch barrier runs, and the manual clock never expires the Stop.
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  const ProgramCommandSchemaRefDTO schema{
      CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  engine.observe_prepared_command_failure =
      ErrorDTO{std::string(to_string(ErrorCode::kExecutionRejected)),
               "injected prepared command read failure",
               {{"reason", "injected_prepared_command_read_failure"}}};
  std::promise<void> prepare_entered;
  std::promise<void> release_prepare;
  auto release_future = release_prepare.get_future().share();
  engine.prepare_command_hook = [&] {
    prepare_entered.set_value();
    release_future.wait();
  };
  auto kernel_heap_test_owner = make_claimed_kernel(
      {registration(make_binding("gripper.target", "tool.gripper.command",
                                 CoordinateKind::kLinear, schema),
                    engine)},
      clock, scheduler, default_journal,
      {kTestApplicationStartId, CellId("cell.test"), 8U});
  auto& kernel = *kernel_heap_test_owner;

  auto executing =
      std::async(std::launch::async, [&] { return kernel.execute(command_operation()); });
  ASSERT_EQ(prepare_entered.get_future().wait_for(std::chrono::seconds(10)),
            std::future_status::ready);
  const OperationAcceptedDTO expected{TestRequestKey("request.command.1"),
                                      RequestReplayStatusDTO::kAcceptedNew,
                                      OperationNumber(1U),
                                      OperationRevision(1U),
                                      {},
                                      0};
  const auto stopped = kernel.stop(stop_request("request.command.prepare.stop", expected, 1U));
  // The Stop started the participant at acceptance (G4); its lane finds the
  // Prepare call in flight and waits for it.
  const bool stop_started = stopped.covered.size() == 1U && stopped.covered.front().started;
  release_prepare.set_value();
  ASSERT_TRUE(stop_started);
  const auto accepted = executing.get();
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  EXPECT_EQ(engine.observe_prepared_command_calls.load(), 1);

  // The end of the preparation borrow wakes the lane, which then settles.
  ASSERT_TRUE(wait_until([&] {
    const auto status = kernel.read_stop(stopped.event_id);
    return status.ok() && status.value().complete;
  }));
  EXPECT_EQ(engine.cancel_prepared_command_calls.load(), 1);
  EXPECT_EQ(engine.dispatch_prepared_command_calls, 0);
  EXPECT_EQ(engine.command_calls, 0);
  EXPECT_EQ(engine.translate_stop_stage_calls.load(), 0);
  const auto status = kernel.read_stop(stopped.event_id);
  ASSERT_TRUE(status.ok()) << status.error().message;
  // The injected read failure is retained as participant evidence only when it
  // is recorded before the Stop's settling pass, so the result is not
  // asserted here; settlement without any effect (no stage) is.
  ASSERT_EQ(status.value().covered.size(), 1U);
  EXPECT_FALSE(status.value().covered.front().containing_stage_index.has_value());
}

