TEST(CellLatchTest, EveryAcceptedStopCallsTheStopListenerOnce) {
  CellLatchFixture fixture;
  struct CountingListener final : IStopListener {
    std::atomic<int> calls{0};
    bool all{};
    void OnStopAccepted(const StopComponentInterrupts& interrupts) noexcept override {
      all = interrupts.all;
      ++calls;
    }
  } listener;
  fixture.kernel.set_stop_listener(&listener);
  fixture.Stop("request.latch.listener.stop");
  EXPECT_EQ(listener.calls.load(), 1);
  EXPECT_TRUE(listener.all);  // Stop all interrupts every action (PD-2)
  // The same request while its record is in the ring is its exact replay:
  // no new event and no component interrupt (§5.4).
  const auto again = fixture.kernel.stop_all(CellLatchFullStop("request.latch.listener.stop"));
  EXPECT_EQ(again.replay_status, RequestReplayStatusDTO::kReplayedExact);
  EXPECT_EQ(listener.calls.load(), 1);
  static_cast<void>(fixture.kernel.stop_all(CellLatchFullStop("request.latch.listener.second")));
  EXPECT_EQ(listener.calls.load(), 2);
}

