TEST(CellLatchTest, WireNamesRoundTrip) {
  for (const auto value : {ComponentLifecycle::kOffline, ComponentLifecycle::kNotPrepared,
                           ComponentLifecycle::kPrepared, ComponentLifecycle::kEnabled,
                           ComponentLifecycle::kFault})
    EXPECT_EQ(parse_component_lifecycle(to_string(value)), value);
  for (const auto value : {CellLatchCauseKind::kFault, CellLatchCauseKind::kOffline,
                           CellLatchCauseKind::kActivityUnknown})
    EXPECT_EQ(parse_cell_latch_cause_kind(to_string(value)), value);
  EXPECT_EQ(to_string(CellLatchCauseKind::kActivityUnknown), "activity_unknown");
  EXPECT_EQ(to_string(FaultCode::kProtectiveStop), "fault_protective_stop");
  EXPECT_EQ(parse_fault_code("fault_vendor"), FaultCode::kVendorFault);
  EXPECT_EQ(to_string(Capability::kIoOutputReadback), "io_output_readback");
  EXPECT_EQ(parse_component_action("reset_position"), ComponentAction::kResetPosition);
  EXPECT_EQ(to_string(Capability::kSimReset), "sim_reset");
  EXPECT_EQ(parse_component_action("sim_reset"), ComponentAction::kSimReset);
  EXPECT_EQ(to_string(ComponentActivity::kUnknown), "unknown");
  EXPECT_EQ(to_string(StreamFreshness::kStale), "stale");
  EXPECT_EQ(to_string(ActionOutcome::kSucceeded), "succeeded");
  EXPECT_EQ(to_string(FaultOperatorAction::kNone), "none");
  EXPECT_FALSE(parse_component_lifecycle("degraded").has_value());
}

TEST(ResourceAddressedExecutionKernelTest,
     StopAllCoversAStoppingParticipantAndStartsFreshWorkWithoutRefenceOrRedispatch) {
  FakeClock clock;
  ManualScheduler scheduler;
  clock.set(100);
  FakeParticipantEngine first_engine;
  FakeParticipantEngine second_engine;
  FakeOperationJournal journal;
  const auto first_binding =
      make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular);
  const auto second_binding = second_same_program_occurrence(first_binding);
  auto kernel_heap_test_owner = make_claimed_kernel(
      {registration(first_binding, first_engine), registration(second_binding, second_engine)},
      clock, scheduler, journal, {kTestApplicationStartId, CellId("cell.test"), 32U});
  auto& kernel = *kernel_heap_test_owner;
  const auto first = kernel.execute(motion_operation("request.aggregate.first.execute"));
  ASSERT_TRUE(first.ok()) << first.error().message;
  auto second_intent = motion_operation("request.aggregate.second.execute");
  second_intent.program_binding_id = second_binding.value().program_binding_id;
  retarget(second_intent.participants.front(), second_binding.value().controllable_component_id,
           second_binding.value().command_target_id);
  const auto second = kernel.execute(second_intent);
  ASSERT_TRUE(second.ok()) << second.error().message;

  std::promise<void> first_stage_entered_promise;
  auto first_stage_entered = first_stage_entered_promise.get_future();
  std::promise<void> release_first_stage_promise;
  const auto release_first_stage = release_first_stage_promise.get_future().share();
  first_engine.translate_stop_stage_hook = [&] {
    first_stage_entered_promise.set_value();
    release_first_stage.wait();
  };
  const auto predecessor =
      kernel.stop(stop_request("request.aggregate.predecessor", first.value(), 1U));
  const auto entered_status = first_stage_entered.wait_for(std::chrono::seconds(10));
  if (entered_status != std::future_status::ready) {
    release_first_stage_promise.set_value();
    FAIL() << "predecessor Stop stage did not reach its blocking seam";
  }

  clock.advance(100);
  // Stop all: the stopping participant is covered (not refenced, no second
  // stage), the fresh one started; the first operation keeps the event that
  // started its attempt.
  const auto all =
      kernel.stop_all(FullStopIntentDTO{{TestRequestKey("request.aggregate.full"), "test"}, {}});
  ASSERT_EQ(all.covered.size(), 2U);
  for (const auto& entry : all.covered) {
    EXPECT_EQ(entry.started, entry.operation_id == second.value().operation_id);
  }
  EXPECT_EQ(stop_accepted_field_error(all), std::nullopt);
  EXPECT_EQ(kernel.get_operation_state(first.value().operation_id).value().stop_event_id,
            predecessor.event_id);
  EXPECT_EQ(kernel.get_operation_state(second.value().operation_id).value().stop_event_id,
            all.event_id);
  EXPECT_EQ(first_engine.addressed_stop_fence_calls.load(), 1);

  // A later stale Stop of the first operation also only covers it.
  const auto later_overlap =
      kernel.stop(stop_request("request.aggregate.later-overlap", first.value(), 1U));
  release_first_stage_promise.set_value();
  ASSERT_EQ(later_overlap.covered.size(), 1U);
  EXPECT_FALSE(later_overlap.covered.front().started);
  EXPECT_EQ(later_overlap.stale_total, 1U);
  EXPECT_EQ(stop_accepted_field_error(later_overlap), std::nullopt);

  ASSERT_TRUE(wait_until(
      [&] { return first_engine.stop_calls.load() == 1 && second_engine.stop_calls.load() == 1; },
      std::chrono::seconds(10)));
  EXPECT_EQ(first_engine.translate_stop_stage_calls.load(), 1);
  EXPECT_EQ(second_engine.translate_stop_stage_calls.load(), 1);
  ASSERT_TRUE(wait_until(
      [&] {
        const auto status = kernel.read_stop(all.event_id);
        return status.ok() && status.value().complete;
      },
      std::chrono::seconds(10)));
  EXPECT_EQ(kernel.read_stop(all.event_id).value().result, StopEventResult::kStopped);
}

