// Signal already active at the send, "must be inactive at start": the
// registration is refused, the candidate's rule is removed and the take-over
// takes the stop-and-restart route with that refusal as its cause.
TEST(ResourceAddressedExecutionKernelTest,
     IoRuleTakeoverSignalActiveAtTheSendTakesTheStopAndRestartRoute) {
  auto fixture = TakeoverRuleFixture();
  ASSERT_NO_FATAL_FAILURE(StartRuleTakeoverRun(fixture));
  const auto original = ExecuteTakeoverMotion(fixture, 0U, "io.takeover.active.original");
  ASSERT_TRUE(original.ok()) << original.error().message;
  const auto candidate = ExecuteTakeoverMotion(fixture, 1U, "io.takeover.active.candidate",
                                               MotionInterruptActivationMode::kRequireInactiveAtArm);
  ASSERT_TRUE(candidate.ok()) << candidate.error().message;
  const auto candidate_id = candidate.value().operation_id;
  ASSERT_TRUE(fixture.Publish(2, true).ok());
  ASSERT_TRUE(fixture.kernel->reconcile_subordinate_state().ok());  // the refused send
  EXPECT_EQ(fixture.engine.dispatch_prepared_motion_calls, 1);
  const auto state = fixture.kernel->get_operation_state(candidate_id).value();
  EXPECT_TRUE(state.participants.front().io_rule_outcomes.empty());
  ASSERT_TRUE(state.motion_takeover);
  EXPECT_NE(state.motion_takeover->path, MotionTakeoverPathDTO::kMovingReplacement);
  ASSERT_TRUE(state.motion_takeover->cause);
  EXPECT_EQ(state.motion_takeover->cause->code, kErrorMotionInterruptSourceActiveAtArm);
  EXPECT_EQ(state.motion_takeover->cause->details.at("reason"), "io_rule_active_at_arm");
  EXPECT_TRUE(fixture.kernel->get_operation_state(original.value().operation_id)
                  .value()
                  .stop_event_id);
  const auto expiry = fixture.kernel->NextIoRuleExpiry();
  ASSERT_TRUE(expiry.ok());
  EXPECT_FALSE(expiry.value());  // no rule is left registered
}

