  const auto candidate_id = candidate.value().operation_id;
  ASSERT_TRUE(fixture.kernel->reconcile_subordinate_state().ok());  // the send
  const auto registration = RuleRegistration(fixture, candidate_id);
  ASSERT_TRUE(registration);
  EXPECT_EQ(observed->retire_calls, 0);
  const auto revision = fixture.kernel->get_operation_state(original.value().operation_id)
                            .value()
                            .operation_revision.value();
  static_cast<void>(fixture.kernel->stop(
      stop_request("io.takeover.stop.operator", original.value(), revision)));
