// Interrupt evaluation is paused during a cell latch, not blind. A
// rule whose condition became true meanwhile trips when the latch ends: the
// Kernel requests rule processing then, and the trip is the level, not a
// lost edge.
TEST(ResourceAddressedExecutionKernelTest, GlobalRuleTrueDuringALatchTripsWhenItEnds) {
  GlobalMotionRuleFixture fixture;
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
  // The default Program runs before the rule holds its scope (Run waits while
  // a rule holds the Program's scope).
  ensure_default_program(*fixture.kernel);
  const auto arm = fixture.binding.value().controllable_component_id.value();
  ComponentState state;
  state.component_id = arm;
  state.lifecycle = ComponentLifecycle::kEnabled;
  state.activity = ComponentActivity::kIdle;
  // The arm is busy when the Stop arrives; a Stop with every component already
  // healthy and idle clears its latch condition at once.
  auto busy = state;
  busy.activity = ComponentActivity::kBusy;
  fixture.kernel->observe_component_states({busy});
  // The cell-wide operator Stop is Stop all (§3.2 S2; `full_stop` removed).
  (void)fixture.kernel->stop_all(CellLatchFullStop("global.latch.stop"));
  auto faulted = state;
  faulted.lifecycle = ComponentLifecycle::kFault;
  faulted.fault = Fault{FaultCode::kProtectiveStop, "protective stop", true,
                        FaultOperatorAction::kRecover, std::nullopt, std::nullopt, {}, 0};
  fixture.kernel->observe_component_states({faulted});
  ASSERT_TRUE(fixture.kernel->get_cell_latch().latched);

  ASSERT_TRUE(fixture.Publish(true).ok());
  ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
  EXPECT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));

  const int before = fixture.processing_requests.load();
  fixture.kernel->observe_component_states({state});
  ASSERT_FALSE(fixture.kernel->get_cell_latch().latched);
  EXPECT_GT(fixture.processing_requests.load(), before);
  ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kTripped));
  // Stop all and then the trip hold every node of the run (§3.2 S2, S7): the
  // node's motion meets the node hold first; with the latch gone, Resume now
  // waits for the rule (`rule_holds`, L1).
  const auto held = fixture.kernel->execute(fixture.Intent(false, "global.latch.after"));
  ASSERT_FALSE(held.ok());
  EXPECT_EQ(held.error().details.at("reason"), "program_node_stop_fence_active");
  const auto scope = fixture.kernel->get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(scope.ok()) << scope.error().message;
  EXPECT_EQ(scope.value().stopped_by_rule_id, std::optional<std::string>("global.guard"));
  const auto resumed = fixture.kernel->release_program_selection(
      program_selection_request("global.latch.after.resume", "all"), scope.value().hold_revision);
  ASSERT_FALSE(resumed.ok());
  EXPECT_EQ(resumed.error().code, "rule_holds");
  EXPECT_EQ(resumed.error().details.at("rule_id"), "global.guard");
}

// A true→false pulse while the cell is latched (evaluation
// paused) is not lost: the registration keeps the trip, so the rule trips
// and then clears when the latch ends.
TEST(ResourceAddressedExecutionKernelTest, GlobalRulePulseDuringALatchTripsWhenItEnds) {
  GlobalMotionRuleFixture fixture;
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
  const auto arm = fixture.binding.value().controllable_component_id.value();
  ComponentState state;
  state.component_id = arm;
  state.lifecycle = ComponentLifecycle::kEnabled;
  state.activity = ComponentActivity::kIdle;
  auto busy = state;
  busy.activity = ComponentActivity::kBusy;
  fixture.kernel->observe_component_states({busy});
  // The cell-wide operator Stop is Stop all (§3.2 S2; `full_stop` removed).
  (void)fixture.kernel->stop_all(CellLatchFullStop("global.latch.pulse"));
  auto faulted = state;
  faulted.lifecycle = ComponentLifecycle::kFault;
  faulted.fault = Fault{FaultCode::kProtectiveStop, "protective stop", true,
                        FaultOperatorAction::kRecover, std::nullopt, std::nullopt, {}, 0};
  fixture.kernel->observe_component_states({faulted});
  ASSERT_TRUE(fixture.kernel->get_cell_latch().latched);

  ASSERT_TRUE(fixture.Publish(true).ok());
  ASSERT_TRUE(fixture.Publish(false).ok());
  ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
  ASSERT_TRUE(drain_journal(*fixture.kernel));
  const auto before = journaled_rule_states(fixture.journal, "global.guard");
  EXPECT_EQ(std::count(before.begin(), before.end(), IoGlobalRuleState::kTripped), 0);

  fixture.kernel->observe_component_states({state});
  ASSERT_FALSE(fixture.kernel->get_cell_latch().latched);
  ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
  EXPECT_TRUE(journaled_trip_then_clear(fixture.journal, "global.guard"));
  EXPECT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
}

// A `stop` + `hold` rule is the operator's Stop. With nothing in its
// scope moving, its trip still holds the run at once (every running node
// held, as the Stop button's group `all`); Resume waits with `rule_holds`.
TEST(ResourceAddressedExecutionKernelTest, GlobalHoldRuleWithNothingMovingHoldsTheRun) {
  GlobalMotionRuleFixture fixture;
  ASSERT_TRUE(claim_program_execution(*fixture.kernel).ok());
  ASSERT_TRUE(fixture.kernel->register_program_run_capture(program_execution_capture()).ok());
  start_program_motion(*fixture.kernel);
  const auto before = fixture.kernel->get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(before.ok()) << before.error().message;
  ASSERT_TRUE(before.value().held_nodes.empty());

  ASSERT_TRUE(fixture.Publish(true).ok());
  ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kTripped));
  const auto held = fixture.kernel->get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(held.ok()) << held.error().message;
  EXPECT_GT(held.value().hold_revision, before.value().hold_revision);
  EXPECT_FALSE(held.value().held_nodes.empty());
  EXPECT_EQ(held.value().stopped_by_rule_id, std::optional<std::string>("global.guard"));
  EXPECT_EQ(fixture.engine.translate_stop_stage_calls, 0);
  // The Kernel's own Resume refuses while the rule holds (not only readiness).
  const auto resumed = fixture.kernel->release_program_selection(
      program_selection_request("global.hold.resume", "all"), held.value().hold_revision);
  ASSERT_FALSE(resumed.ok());
  EXPECT_EQ(resumed.error().code, "rule_holds");
  EXPECT_EQ(resumed.error().details.at("rule_id"), "global.guard");
  EXPECT_FALSE(fixture.kernel->get_cell_latch().latched);
  // The held node's own motion is refused by the hold itself.
  const auto refused = fixture.kernel->execute(scoped_motion_operation("global.hold.next"));
  ASSERT_FALSE(refused.ok());
  EXPECT_EQ(refused.error().details.at("reason"), "program_node_stop_fence_active");
}

// OD-263: a `hold` rule's Stop covers the held run's move still being
// prepared, as the operator's Stop does: it is stopped before sending (no
// effect, never `rule_holds`), the node holds, and after the rule clears
// Resume plans the move again.
TEST(ResourceAddressedExecutionKernelTest, GlobalHoldRuleTripWhileAMoveIsPreparingHoldsTheMove) {
  GlobalMotionRuleFixture fixture;
  auto& kernel = *fixture.kernel;
  ASSERT_TRUE(claim_program_execution(kernel).ok());
  ASSERT_TRUE(kernel.register_program_run_capture(program_execution_capture()).ok());
  start_program_motion(kernel);
  fixture.engine.defer_prepare_completion = true;
  const auto accepted = kernel.execute(scoped_motion_operation("global.hold.preparing"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  const auto id = accepted.value().operation_id;

  ASSERT_TRUE(fixture.Publish(true).ok());
  ASSERT_TRUE(kernel.ProcessIoRuleEvidence().ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kTripped));
  const auto held = kernel.get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(held.ok()) << held.error().message;
  EXPECT_FALSE(held.value().held_nodes.empty());
  EXPECT_EQ(held.value().stopped_by_rule_id, std::optional<std::string>("global.guard"));
  // The hold's own Stop event covers the unsent move at once.
  const auto covered = kernel.get_operation_state(id);
  ASSERT_TRUE(covered.ok()) << covered.error().message;
  ASSERT_TRUE(covered.value().stop_event_id.has_value());
  const auto event = *covered.value().stop_event_id;

  (void)fixture.engine.complete_preparation();
  ASSERT_TRUE(wait_until([&] {
    const auto state = kernel.get_operation_state(id);
    return state.ok() && terminal(state.value().state);
  }));
  ASSERT_TRUE(wait_stop_complete(kernel, event));
  const auto ended = kernel.get_operation_state(id);
  ASSERT_TRUE(ended.ok()) << ended.error().message;
  EXPECT_EQ(ended.value().state, OperationStateKind::kStopped);
  EXPECT_EQ(ended.value().stop_event_id, std::optional<StopEventId>(event));
  const auto& row = ended.value().participants.front();
  EXPECT_FALSE(row.terminal_error.has_value());
  ASSERT_TRUE(row.terminal_fact.has_value());
  EXPECT_EQ(row.terminal_fact->kind, ParticipantExecutionFactKind::kCancelledBeforeDispatch);
  EXPECT_EQ(row.terminal_fact->effect, ParticipantEffectKnowledge::kNoEffect);
  EXPECT_EQ(fixture.engine.dispatch_prepared_motion_calls, 0);
  EXPECT_EQ(fixture.engine.execute_calls, 0);
  const auto projection = kernel.get_operation_projection(id);
  ASSERT_TRUE(projection.ok()) << projection.error().message;
  EXPECT_TRUE(projection.value().resident);  // Held for Resume, not retired.
  const auto recovery = kernel.get_operation_recovery_assessment(id);
  ASSERT_TRUE(recovery.ok()) << recovery.error().message;
  EXPECT_EQ(recovery.value().assessment.recovery_class, RecoveryClass::kOrdinaryOperatorStop);
  EXPECT_EQ(recovery.value().assessment.status, RecoveryAssessmentStatus::kRetryReady);

  // Resume waits for the rule; once it clears, the Program's Resume replans
  // the held move and its next attempt is planned and sent.
  ASSERT_TRUE(fixture.Publish(false).ok());
  ASSERT_TRUE(kernel.ProcessIoRuleEvidence().ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
  KernelRecoveryActionRequestDTO replan{TestRequestKey("global.hold.preparing.replan"),
                                        RecoveryAction::kReplanFromStoppedState,
                                        "program_runner", 1U, 1U, 41U, "resume"};
  fixture.engine.next_recovery_result = {replan.request_key, replan.action, true, {},
                                         std::nullopt};
  const auto replanned = kernel.apply_operation_recovery_action(
      id, ended.value().operation_revision, replan);
  ASSERT_TRUE(replanned.ok()) << replanned.error().message;
  ASSERT_TRUE(replanned.value().accepted);
  const auto cleared = kernel.get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(cleared.ok()) << cleared.error().message;
  const auto resumed = kernel.release_program_selection(
      program_selection_request("global.hold.preparing.resume", "all"),
      cleared.value().hold_revision);
  ASSERT_TRUE(resumed.ok()) << resumed.error().message;
  EXPECT_TRUE(resumed.value().held_nodes.empty());
  fixture.engine.defer_prepare_completion = false;
  // The fake keeps one prepared slot: the cancelled one makes room.
  fixture.engine.prepared_snapshot.reset();
  fixture.engine.next_execution_id = 42U;
  fixture.engine.next_execute_result = Result<std::uint64_t>::Ok(42U);
  const int prepared_before = fixture.engine.prepare_motion_calls;
  auto next = scoped_motion_operation("global.hold.preparing.next");
  next.participants.front().execution_scope->node_attempt_id = NodeAttemptNumber(2U);
  const auto again = kernel.execute(next);
  ASSERT_TRUE(again.ok()) << again.error().message;
  EXPECT_GT(fixture.engine.prepare_motion_calls, prepared_before);
  EXPECT_TRUE(wait_until([&] { return fixture.engine.dispatch_prepared_motion_calls == 1; }));
}

// OD-264 (Kernel side, unchanged): the operator's group Stop during a
// take-over whose newcomer is still preparing ends the newcomer Stopped by
// that Stop with no effect, retired at once; the Program holds its node.
TEST(ResourceAddressedExecutionKernelTest, GroupStopDuringATakeoverEndsThePreparingNewcomerWithNoEffect) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  engine.supports_motion_replacement = true;
  auto row = registration(
      make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular), engine);
  row.motion_takeover_preparation_budget_s = 1.0;
  ResourceAddressedExecutionKernelConfig config{kTestApplicationStartId, CellId("cell.test"), 8U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  auto owner = make_uncaptured_kernel({row}, clock, scheduler, journal, std::move(config));
  auto& kernel = *owner;
  ASSERT_TRUE(claim_program_execution(kernel).ok());
  auto capture = program_execution_capture();
  {
    auto table = std::make_shared<ProgramExecutionTableDTO>();
    const auto prototype = capture.table->nodes.front();
    for (std::size_t index = 0U; index != 2U; ++index) {
      auto node = prototype;
      node.instance_id = ProgramNodeInstanceId("move." + std::to_string(index));
      table->nodes.push_back(std::move(node));
    }
    table->named_selections = {{"arm", {0U, 1U}}};
    capture.table = std::move(table);
  }
  ASSERT_TRUE(kernel.register_program_run_capture(capture).ok());
  start_program_motion(kernel);
  const auto intent_for = [](const std::size_t node, std::string request) {
    auto intent = scoped_motion_operation(std::move(request));
    intent.participants.front().execution_scope = ProgramNodeExecutionScopeDTO{
        ProgramNodeInstanceId("move." + std::to_string(node)), NodeAttemptNumber(1U)};
    return intent;
  };
  const auto incumbent = kernel.execute(intent_for(0U, "takeover.stop.incumbent"));
  ASSERT_TRUE(incumbent.ok()) << incumbent.error().message;
  engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
  ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
  engine.defer_prepare_completion = true;
  const auto candidate = kernel.execute(intent_for(1U, "takeover.stop.newcomer"));
  ASSERT_TRUE(candidate.ok()) << candidate.error().message;
  const auto newcomer = candidate.value().operation_id;
  (void)kernel.reconcile_subordinate_state();

  const auto stopped = kernel.stop_program_selection(program_selection_request("takeover.stop", "all"));
  ASSERT_TRUE(stopped.state.has_value());
  (void)engine.complete_preparation();
  ASSERT_TRUE(wait_until([&] {
    (void)kernel.reconcile_subordinate_state();
    const auto state = kernel.get_operation_state(newcomer);
    return state.ok() && terminal(state.value().state);
  }));
  const auto ended = kernel.get_operation_state(newcomer);
  ASSERT_TRUE(ended.ok()) << ended.error().message;
  EXPECT_EQ(ended.value().state, OperationStateKind::kStopped);
  EXPECT_EQ(ended.value().stop_event_id, std::optional<StopEventId>(stopped.stop.event_id));
  const auto& fact = ended.value().participants.front();
  EXPECT_FALSE(fact.terminal_error.has_value());
  ASSERT_TRUE(fact.terminal_fact.has_value());
  EXPECT_EQ(fact.terminal_fact->kind, ParticipantExecutionFactKind::kCancelledBeforeDispatch);
  EXPECT_EQ(fact.terminal_fact->effect, ParticipantEffectKnowledge::kNoEffect);
  const auto projection = kernel.get_operation_projection(newcomer);
  ASSERT_TRUE(projection.ok()) << projection.error().message;
  EXPECT_FALSE(projection.value().resident);
  const auto scope = kernel.get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(scope.ok()) << scope.error().message;
  EXPECT_EQ(scope.value().held_nodes.size(), 2U);
}

// OD-269: the operator's group Stop ends a take-over newcomer that was
// already sent (its effect settled, retired at once). The Kernel keeps its
// rest for the node's next attempt, as Resume keeps it for any stopped
// motion; the slot is released when that attempt completes. Without a
// verified send, or for a Cartesian path (its progress is unknown before
// the hand-over), that attempt is refused as such a Resume is. A newcomer
// never sent keeps nothing: the next attempt is a fresh one.
TEST(ResourceAddressedExecutionKernelTest,
     GroupStopDuringATakeoverKeepsTheSentNewcomersRestForItsNextAttempt) {
  enum class Newcomer { kSentJoint, kSentCartesian, kSentUnverified, kUnsent };
  for (const auto kind : {Newcomer::kSentJoint, Newcomer::kSentCartesian,
                          Newcomer::kSentUnverified, Newcomer::kUnsent}) {
    SCOPED_TRACE(static_cast<int>(kind));
    const bool sent = kind != Newcomer::kUnsent;
    FakeClock clock;
    ManualScheduler scheduler;
    FakeParticipantEngine engine;
    FakeOperationJournal journal;
    engine.supports_motion_replacement = true;
    engine.replacement_send_receipt_missing = kind == Newcomer::kSentUnverified;
    const auto physical =
        make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular);
    const auto row_for = [&](const RuntimeParticipantBinding& binding) {
      auto row = registration(binding, engine);
      row.motion_takeover_preparation_budget_s = 1.0;
      return row;
    };
    ResourceAddressedExecutionKernelConfig config{kTestApplicationStartId, CellId("cell.test"), 8U};
    config.manager_liveness_required_set = EmptyManagerLivenessSet();
    if (kind == Newcomer::kSentCartesian) {
      const auto cartesian = with_planner_capability(physical, "planning.motion.cartesian_path");
      config.participant_resolver =
          [&, cartesian](const OperationIntentDTO& operation, const std::size_t,
                         const ProgramRunResolutionContext&)
          -> Result<RuntimeParticipantExecutionRegistration> {
        const auto& motion =
            std::get<MotionParticipantIntentDTO>(operation.participants.front().payload);
        return Result<RuntimeParticipantExecutionRegistration>::Ok(
            row_for(std::holds_alternative<CartesianPathDTO>(motion.motion) ? cartesian
                                                                            : physical));
      };
    }
    auto owner = make_uncaptured_kernel({row_for(physical)}, clock, scheduler, journal,
                                        std::move(config));
    auto& kernel = *owner;
    ASSERT_TRUE(kernel.register_program_run_capture(takeover_capture()).ok());
    start_program_motion(kernel);
    const auto incumbent = kernel.execute(takeover_intent(0U, "od269.incumbent"));
    ASSERT_TRUE(incumbent.ok()) << incumbent.error().message;
    engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
    ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
    auto newcomer_intent = takeover_intent(1U, "od269.newcomer");
    if (kind == Newcomer::kSentCartesian) {
      auto& motion =
          std::get<MotionParticipantIntentDTO>(newcomer_intent.participants.front().payload);
      motion.motion = CartesianPathDTO{.waypoints = {Pose3DTO{}, Pose3DTO{{0.0, 0.0, 0.1}, {}}}};
      motion.per_joint_dynamics_limits.clear();
    }
    engine.defer_prepare_completion = !sent;
    const auto newcomer = kernel.execute(newcomer_intent);
    ASSERT_TRUE(newcomer.ok()) << newcomer.error().message;
    const auto newcomer_id = newcomer.value().operation_id;
    std::optional<ResolvedMotionSpecDTO> sent_motion;
    if (sent) {
      ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());  // the send
      ASSERT_EQ(engine.dispatch_prepared_motion_calls.load(), 2);
      std::lock_guard lock(engine.prepared_motion_mutex_);
      ASSERT_TRUE(engine.replacement_snapshot && engine.replacement_snapshot->participant);
      sent_motion = std::get<PreparedMotionExecutionDTO>(
                        engine.replacement_snapshot->participant->payload)
                        .plan_request.motion;
    } else {
      (void)kernel.reconcile_subordinate_state();
    }

    const auto stopped =
        kernel.stop_program_selection(program_selection_request("od269.stop", "all"));
    ASSERT_TRUE(stopped.state.has_value());
    if (!sent) (void)engine.complete_preparation();
    // As the host's reconcile lane: a pass before the incumbent's Stop has
    // ended leaves a sent newcomer stopping and pending (OD-272); the first
    // pass after it ends the newcomer settled and retires it.
    ASSERT_TRUE(wait_until([&] {
      (void)kernel.reconcile_subordinate_state();
      const auto stop = kernel.read_stop(stopped.stop.event_id);
      const auto projection = kernel.get_operation_projection(newcomer_id);
      return stop.ok() && stop.value().complete && projection.ok() &&
             !projection.value().resident;
    }));
    const auto ended = kernel.get_operation_state(newcomer_id);
    ASSERT_TRUE(ended.ok()) << ended.error().message;
    EXPECT_EQ(ended.value().state, OperationStateKind::kStopped);
    const auto& row = ended.value().participants.front();
    EXPECT_FALSE(row.terminal_error.has_value());
    ASSERT_TRUE(row.terminal_fact.has_value());
    EXPECT_EQ(row.terminal_fact->kind,
              sent ? ParticipantExecutionFactKind::kPreemptedByAddressedStop
                   : ParticipantExecutionFactKind::kCancelledBeforeDispatch);
    EXPECT_EQ(row.terminal_fact->effect, sent ? ParticipantEffectKnowledge::kEffectSettled
                                              : ParticipantEffectKnowledge::kNoEffect);
    EXPECT_FALSE(kernel.get_operation_projection(newcomer_id).value().resident);

    // Resume: the stopped incumbent is retired by its own Resume, the run's
    // hold is released, and the newcomer's node makes its next attempt.
    const auto source = kernel.get_operation_state(incumbent.value().operation_id);
    ASSERT_TRUE(source.ok()) << source.error().message;
    KernelRecoveryActionRequestDTO replan{TestRequestKey("od269.replan"),
                                          RecoveryAction::kReplanFromStoppedState,
                                          "program_runner", 1U, 1U, 41U, "resume"};
    engine.next_recovery_result = {replan.request_key, replan.action, true, {}, std::nullopt};
    const auto replanned = kernel.apply_operation_recovery_action(
        incumbent.value().operation_id, source.value().operation_revision, replan);
    ASSERT_TRUE(replanned.ok()) << replanned.error().message;
    ASSERT_TRUE(replanned.value().accepted);
    const auto held = kernel.get_program_execution_scope(ProgramRunNumber(1U));
    ASSERT_TRUE(held.ok()) << held.error().message;
    ASSERT_TRUE(kernel
                    .release_program_selection(program_selection_request("od269.resume", "all"),
                                               held.value().hold_revision)
                    .ok());
    auto next = newcomer_intent;
    next.request_context.request_key = TestRequestKey("od269.next");
    next.participants.front().execution_scope->node_attempt_id = NodeAttemptNumber(2U);
    const int prepared_before = engine.prepare_motion_calls.load();
    const auto again = kernel.execute(next);
    if (kind == Newcomer::kSentCartesian || kind == Newcomer::kSentUnverified) {
      ASSERT_FALSE(again.ok());
      EXPECT_EQ(again.error().code, "operation_recovery_invalid");
      EXPECT_EQ(again.error().details.at("reason"),
                kind == Newcomer::kSentCartesian ? "cartesian_resume_progress_unavailable"
                                                 : "motion_continuation_dispatch_unsettled");
      EXPECT_EQ(engine.prepare_motion_calls.load(), prepared_before);
      continue;
    }
    ASSERT_TRUE(again.ok()) << again.error().message;
    ASSERT_TRUE(engine.last_prepared_request);
    if (!sent) {
      EXPECT_FALSE(engine.last_prepared_request->continuation);
      continue;
    }
    ASSERT_TRUE(engine.last_prepared_request->continuation);
    EXPECT_EQ(engine.last_prepared_request->continuation->motion, *sent_motion);
    // Released when the attempt that planned the rest completes.
    engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kCompleted);
    const auto current = kernel.get_operation_state(again.value().operation_id);
    ASSERT_TRUE(current.ok()) << current.error().message;
    ASSERT_TRUE(kernel
                    .acknowledge_completed(control_request("od269.ack", again.value(),
                                                           current.value().operation_revision.value()))
                    .ok());
    ASSERT_TRUE(wait_until([&] {
      return !kernel.get_operation_projection(again.value().operation_id).value().resident;
    }));
    next.request_context.request_key = TestRequestKey("od269.next-visit");
    next.participants.front().execution_scope->node_attempt_id = NodeAttemptNumber(3U);
    ASSERT_TRUE(kernel.execute(next).ok());
    ASSERT_TRUE(engine.last_prepared_request);
    EXPECT_FALSE(engine.last_prepared_request->continuation);
  }
}

// OD-272: while the old motion's Stop has not ended, a sent newcomer that
// the Stop cancelled stays stopping (no terminal fact or error, resident),
// as any moving motion under a Stop; once that Stop ends settled, it ends
// Stopped with its effect settled and is retired.
TEST(ResourceAddressedExecutionKernelTest,
     GroupStopKeepsASentNewcomerStoppingUntilTheOldMotionsStopEnds) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  engine.supports_motion_replacement = true;
  auto row = registration(
      make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular), engine);
  row.motion_takeover_preparation_budget_s = 1.0;
  ResourceAddressedExecutionKernelConfig config{kTestApplicationStartId, CellId("cell.test"), 8U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  auto owner = make_uncaptured_kernel({row}, clock, scheduler, journal, std::move(config));
  auto& kernel = *owner;
  ASSERT_TRUE(kernel.register_program_run_capture(takeover_capture()).ok());
  start_program_motion(kernel);
  const auto incumbent = kernel.execute(takeover_intent(0U, "od272.incumbent"));
  ASSERT_TRUE(incumbent.ok()) << incumbent.error().message;
  engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
  ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
  const auto newcomer = kernel.execute(takeover_intent(1U, "od272.newcomer"));
  ASSERT_TRUE(newcomer.ok()) << newcomer.error().message;
  const auto newcomer_id = newcomer.value().operation_id;
  ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());  // the send
  ASSERT_EQ(engine.dispatch_prepared_motion_calls.load(), 2);

  // The old motion's Stop is held in its stage: it has not ended.
  HeldSettlementCall stage;
  engine.translate_stop_stage_hook = stage.Blocker();
  const auto stopped =
      kernel.stop_program_selection(program_selection_request("od272.stop", "all"));
  ASSERT_TRUE(stopped.state.has_value());
  ASSERT_TRUE(stage.Entered());
  for (int pass = 0; pass < 3; ++pass) (void)kernel.reconcile_subordinate_state();
  const auto stopping = kernel.get_operation_projection(newcomer_id);
  ASSERT_TRUE(stopping.ok()) << stopping.error().message;
  EXPECT_TRUE(stopping.value().resident);
  EXPECT_EQ(stopping.value().operation.state, OperationStateKind::kStopping);
  EXPECT_EQ(stopping.value().operation.stop_event_id, stopped.stop.event_id);
  const auto& stopping_row = stopping.value().operation.participants.front();
  EXPECT_EQ(stopping_row.state, OperationStateKind::kStopping);
  EXPECT_FALSE(stopping_row.terminal_error.has_value());
  EXPECT_FALSE(stopping_row.terminal_fact.has_value());
  EXPECT_FALSE(kernel.read_stop(stopped.stop.event_id).value().complete);

  stage.Release();
  ASSERT_TRUE(wait_until([&] {
    (void)kernel.reconcile_subordinate_state();
    const auto stop = kernel.read_stop(stopped.stop.event_id);
    const auto projection = kernel.get_operation_projection(newcomer_id);
    return stop.ok() && stop.value().complete && projection.ok() &&
           !projection.value().resident;
  }));
  const auto ended = kernel.get_operation_state(newcomer_id);
  ASSERT_TRUE(ended.ok()) << ended.error().message;
  EXPECT_EQ(ended.value().state, OperationStateKind::kStopped);
  const auto& ended_row = ended.value().participants.front();
  EXPECT_FALSE(ended_row.terminal_error.has_value());
  ASSERT_TRUE(ended_row.terminal_fact.has_value());
  EXPECT_EQ(ended_row.terminal_fact->kind, ParticipantExecutionFactKind::kPreemptedByAddressedStop);
  EXPECT_EQ(ended_row.terminal_fact->effect, ParticipantEffectKnowledge::kEffectSettled);
}

// `fail_node` keeps the run going: no hold; the next motion in scope
// fails at once with `rule_holds` and the tree handles it.
TEST(ResourceAddressedExecutionKernelTest, GlobalFailNodeRuleWithNothingMovingLeavesTheRunGoing) {
  GlobalMotionRuleFixture fixture(false, true, IoRuleOnTripDTO::kStop,
                                  IoRuleAfterStopDTO::kFailNode);
  ASSERT_TRUE(claim_program_execution(*fixture.kernel).ok());
  ASSERT_TRUE(fixture.kernel->register_program_run_capture(program_execution_capture()).ok());
  start_program_motion(*fixture.kernel);
  const auto before = fixture.kernel->get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(before.ok()) << before.error().message;

  ASSERT_TRUE(fixture.Publish(true).ok());
  ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kTripped));
  const auto after = fixture.kernel->get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(after.ok()) << after.error().message;
  EXPECT_EQ(after.value().hold_revision, before.value().hold_revision);
  EXPECT_TRUE(after.value().held_nodes.empty());
  // The running node's next motion in scope fails at once.
  const auto refused = fixture.kernel->execute(scoped_motion_operation("global.fail-node.next"));
  ASSERT_FALSE(refused.ok());
  EXPECT_EQ(refused.error().code, "rule_holds");
  EXPECT_EQ(refused.error().details.at("rule_id"), "global.guard");
}

// Any active rule that can't watch (missing first sample, stale) gates its
// scope with `rule_holds`, withdraws its key, issues no Stop, never latches,
// and clears by itself once a fresh sample rearms it.
TEST(ResourceAddressedExecutionKernelTest, GlobalRuleThatCantWatchGatesItsScopeUntilFresh) {
  for (const auto on_trip : {IoRuleOnTripDTO::kStop, IoRuleOnTripDTO::kNotify}) {
    for (const bool initial : {false, true}) {
      SCOPED_TRACE(static_cast<int>(on_trip) * 2 + static_cast<int>(initial));
      GlobalMotionRuleFixture fixture(true, initial, on_trip);
      if (initial) {
        // The default Program runs while the rule still watches.
        ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
        ensure_default_program(*fixture.kernel);
        fixture.clock.advance(101);  // The baseline reading goes stale.
        ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
      }
      ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kUnknown));
      if (initial) {
        const auto blocked = fixture.kernel->execute(fixture.Intent(false, "global.unwatched"));
        ASSERT_FALSE(blocked.ok());
        EXPECT_EQ(blocked.error().code, "rule_holds");
        EXPECT_EQ(blocked.error().details.at("rule_id"), "global.guard");
        EXPECT_TRUE(fixture.kernel->execute(fixture.Intent(true, "global.unwatched.other")).ok());
      } else {
        // Never watched: the Program that meets the rule's scope cannot Run
        // (Run waits while a rule holds the Program's scope, L2), so none of
        // its motion, disjoint included, starts before a fresh sample.
        const auto claim = claim_program_execution(*fixture.kernel);
        ASSERT_TRUE(claim.ok()) << claim.error().message;
        ASSERT_TRUE(fixture.kernel
                        ->register_program_run_capture(
                            default_program_capture(claim.value().claim_generation))
                        .ok());
        const auto scope = fixture.kernel->get_program_execution_scope(ProgramRunNumber(1U));
        ASSERT_TRUE(scope.ok()) << scope.error().message;
        const auto run = fixture.kernel->start_program_selection(
            program_selection_request("global.unwatched.run", "all"), scope.value().hold_revision);
        ASSERT_FALSE(run.ok());
        EXPECT_EQ(run.error().code, "rule_holds");
        EXPECT_EQ(run.error().details.at("rule_id"), "global.guard");
      }
      EXPECT_EQ(fixture.engine.translate_stop_stage_calls, 0);
      EXPECT_FALSE(fixture.kernel->get_cell_latch().latched);
      ASSERT_TRUE(fixture.Publish(false).ok());
      ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
      ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
      EXPECT_TRUE(fixture.kernel->ReadRuleHolds().empty());
      if (!initial) start_program_motion(*fixture.kernel);  // Run, now that it watches
      const auto allowed = fixture.kernel->execute(fixture.Intent(false, "global.watching"));
      EXPECT_TRUE(allowed.ok()) << allowed.error().message;
    }
  }
}

// OD-258: a move refused by a global I/O rule at the final pre-dispatch
// recheck fails at once with no effect (CONTRACTS §8); its operation is not
// kept resident, so the same robot's next move is admitted.
TEST(ResourceAddressedExecutionKernelTest, GlobalRuleRefusalBeforeDispatchEndsTheMoveAndFreesTheRobot) {
  GlobalMotionRuleFixture fixture(true, true, IoRuleOnTripDTO::kNotify);
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
  ensure_default_program(*fixture.kernel);
  fixture.engine.defer_prepare_completion = true;
  const auto accepted = fixture.kernel->execute(fixture.Intent(false, "global.predispatch"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  fixture.clock.advance(101);  // The reading goes stale: the rule can't watch.
  ASSERT_TRUE(fixture.engine.complete_preparation().ok());
  ASSERT_TRUE(wait_until([&] {
    const auto projection = fixture.kernel->get_operation_projection(accepted.value().operation_id);
    return projection.ok() && !projection.value().resident;
  }));
  EXPECT_EQ(fixture.engine.dispatch_prepared_motion_calls, 0);
  EXPECT_EQ(fixture.engine.execute_calls, 0);
  EXPECT_EQ(fixture.engine.cancel_prepared_motion_calls, 1);
  const auto state = fixture.kernel->get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(state.ok()) << state.error().message;
  ASSERT_EQ(state.value().participants.size(), 1U);
  ASSERT_TRUE(state.value().participants.front().terminal_error.has_value());
  EXPECT_EQ(state.value().participants.front().terminal_error->code, "rule_holds");

  ASSERT_TRUE(fixture.Publish(false).ok());
  ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
  const auto next = fixture.kernel->execute(fixture.Intent(false, "global.predispatch.next"));
  EXPECT_TRUE(next.ok()) << next.error().message;
}

// Any active rule (stop or notify) that loses its signals while motion in its
// scope moves issues the operator's Stop on that scope: the row stays Stopped
// for Resume and its fact names the rule; disjoint motion keeps moving; then
// the rule holds its scope without a latch and clears by itself.
TEST(ResourceAddressedExecutionKernelTest, GlobalRuleLosingItsSignalsStopsMovingMotionInScope) {
  for (const auto on_trip : {IoRuleOnTripDTO::kStop, IoRuleOnTripDTO::kNotify}) {
    SCOPED_TRACE(static_cast<int>(on_trip));
    GlobalMotionRuleFixture fixture(true, true, on_trip);
    const auto motion = fixture.kernel->execute(fixture.Intent());
    const auto other = fixture.kernel->execute(fixture.Intent(true, "global.lost.disjoint"));
    ASSERT_TRUE(motion.ok()) << motion.error().message;
    ASSERT_TRUE(other.ok()) << other.error().message;
    fixture.clock.advance(101);  // The reading goes stale while moving.
    ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
    ASSERT_TRUE(wait_until([&] { return fixture.Certified(motion.value().operation_id); }));
    const auto ended = fixture.kernel->get_operation_state(motion.value().operation_id).value();
    const auto& row = ended.participants.front();
    EXPECT_NE(row.state, OperationStateKind::kFailed);
    ASSERT_TRUE(row.terminal_fact);
    ASSERT_TRUE(row.terminal_fact->error);
    EXPECT_EQ(row.terminal_fact->error->code, "interrupt_source_unavailable");
    EXPECT_EQ(row.terminal_fact->error->details.at("stopped_by"), "rule");
    EXPECT_EQ(row.terminal_fact->error->details.at("rule_id"), "global.guard");
    EXPECT_EQ(fixture.kernel->get_operation_state(other.value().operation_id).value().state,
              OperationStateKind::kExecuting);
    EXPECT_FALSE(fixture.kernel->get_cell_latch().latched);
    ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kUnknown));
    EXPECT_EQ(fixture.kernel->ReadRuleHolds().size(), 1U);
    ASSERT_TRUE(fixture.Publish(false).ok());
    ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
    ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
    EXPECT_TRUE(fixture.kernel->ReadRuleHolds().empty());
  }
}

// Activation: an inactive rule doesn't watch, trip, stop or gate (`inactive`);
// activating it while its condition holds trips it at once; reset returns
// every rule to `active_at_start`.
TEST(ResourceAddressedExecutionKernelTest, GlobalRuleActivationTripsAtOnceAndResets) {
  GlobalMotionRuleFixture fixture(true, true, IoRuleOnTripDTO::kStop, IoRuleAfterStopDTO::kHold,
                                  {}, 20, "global.guard", false, false, false, nullptr, false,
                                  false, false);
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kInactive));
  ASSERT_TRUE(fixture.Publish(true).ok());
  ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
  EXPECT_TRUE(fixture.kernel->ReadRuleHolds().empty());
  const auto motion = fixture.kernel->execute(fixture.Intent());
  ASSERT_TRUE(motion.ok()) << motion.error().message;
  const auto unknown = fixture.kernel->set_rule_active(InterruptPolicyId("global.missing"), true);
  ASSERT_FALSE(unknown.ok());
  EXPECT_EQ(unknown.error().code, "rule_unknown");
  ASSERT_TRUE(fixture.kernel->set_rule_active(InterruptPolicyId("global.guard"), true).ok());
  ASSERT_TRUE(wait_until([&] { return fixture.Certified(motion.value().operation_id); }));
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kTripped));
  EXPECT_EQ(fixture.kernel->ReadRuleHolds().size(), 1U);
  ASSERT_TRUE(fixture.kernel->reset_rule_activation().ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kInactive));
  EXPECT_TRUE(fixture.kernel->ReadRuleHolds().empty());
}

// A planned source disable leaves an active rule unable to watch: it gates
// only its scope, never latches, and a fresh sample rearms it.
TEST(ResourceAddressedExecutionKernelTest, GlobalRulePlannedSourceDisableHoldsOnlyItsScope) {
  GlobalMotionRuleFixture fixture(true, true, IoRuleOnTripDTO::kStop, IoRuleAfterStopDTO::kHold,
                                  {}, 20, "global.guard", false, false, false, nullptr, false,
                                  true);
  ASSERT_TRUE(ready_cell_admission(*fixture.kernel).ok());
  ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
  // A planned source disable needs an idle cell with no Program claim, so it
  // comes before the Program.
  ASSERT_TRUE(planned_global_source_change(fixture, true).ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kUnknown));
  // The Program that meets the rule's scope cannot Run while the rule can't
  // watch (Run waits while a rule holds the Program's scope, L2).
  const auto claim = claim_program_execution(*fixture.kernel);
  ASSERT_TRUE(claim.ok()) << claim.error().message;
  ASSERT_TRUE(fixture.kernel
                  ->register_program_run_capture(
                      default_program_capture(claim.value().claim_generation))
                  .ok());
  const auto scope = fixture.kernel->get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(scope.ok()) << scope.error().message;
  const auto blocked = fixture.kernel->start_program_selection(
      program_selection_request("global.planned.blocked", "all"), scope.value().hold_revision);
  ASSERT_FALSE(blocked.ok());
  EXPECT_EQ(blocked.error().code, "rule_holds");
  EXPECT_EQ(blocked.error().details.at("rule_id"), "global.guard");
  EXPECT_FALSE(fixture.kernel->get_cell_latch().latched);
  ASSERT_TRUE(planned_global_source_change(fixture, false).ok());
  ASSERT_TRUE(fixture.Publish(false).ok());
  ASSERT_TRUE(fixture.kernel->ProcessIoRuleEvidence().ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
  start_program_motion(*fixture.kernel);  // Run, now that it watches
  const auto allowed = fixture.kernel->execute(fixture.Intent(false, "global.planned.after"));
  EXPECT_TRUE(allowed.ok()) << allowed.error().message;
}

// A component that becomes `prepared` starts its outputs'
// core-held `changed_outside` signals false; staying prepared changes nothing.
TEST(ResourceAddressedExecutionKernelTest, ComponentBecomingPreparedClearsItsOutsideChanges) {
  GlobalRuleCatalogFixture fixture;
  const auto source = fixture.Service(9U);
  const auto observed = std::make_shared<GlobalRuleCatalogObservedService>(source);
  ASSERT_TRUE(fixture.kernel->SetRouteRecoveryPending(true).ok());
  ASSERT_TRUE(fixture.kernel->RestoreGlobalIoRuleCatalog(
      fixture.context, fixture.EmptyCatalog(fixture.context, source), observed).ok());
  ASSERT_TRUE(fixture.kernel->SetRouteRecoveryPending(false).ok());
  ComponentState io;
  io.component_id = "gripper.io";
  io.lifecycle = ComponentLifecycle::kNotPrepared;
  io.activity = ComponentActivity::kIdle;
  fixture.kernel->observe_component_states({io});
  EXPECT_TRUE(observed->cleared_components.empty());
  io.lifecycle = ComponentLifecycle::kPrepared;
  fixture.kernel->observe_component_states({io});
  fixture.kernel->observe_component_states({io});
  EXPECT_EQ(observed->cleared_components, std::vector<std::string>{"gripper.io"});
  io.lifecycle = ComponentLifecycle::kEnabled;
  fixture.kernel->observe_component_states({io});
  io.lifecycle = ComponentLifecycle::kPrepared;
  fixture.kernel->observe_component_states({io});
  EXPECT_EQ(observed->cleared_components, (std::vector<std::string>{"gripper.io", "gripper.io"}));
}

TEST(ResourceAddressedExecutionKernelTest, EstopPresentationDoesNotClearOutsideChanges) {
  GlobalRuleCatalogFixture fixture;
  const auto source = fixture.Service(9U);
  const auto observed = std::make_shared<GlobalRuleCatalogObservedService>(source);
  ASSERT_TRUE(fixture.kernel->SetRouteRecoveryPending(true).ok());
  ASSERT_TRUE(fixture.kernel->RestoreGlobalIoRuleCatalog(
      fixture.context, fixture.EmptyCatalog(fixture.context, source), observed).ok());
  ASSERT_TRUE(fixture.kernel->SetRouteRecoveryPending(false).ok());

  ComponentState owner;
  owner.component_id = "machine";
  owner.lifecycle = ComponentLifecycle::kPrepared;
  owner.activity = ComponentActivity::kIdle;
  ComponentState io;
  io.component_id = "gripper.io";
  io.owner_id = owner.component_id;
  io.lifecycle = ComponentLifecycle::kEnabled;
  io.activity = ComponentActivity::kIdle;
  fixture.kernel->observe_component_states({owner, io});
  observed->cleared_components.clear();

  owner.stop = ComponentStop{StopCode::kEstop, "E-stop not cleared", "C2", "Emergency stop", 1};
  const auto projected = presented_member_state(io, owner);
  ASSERT_EQ(projected.lifecycle, ComponentLifecycle::kPrepared);
  fixture.kernel->observe_component_states({owner, projected});
  EXPECT_TRUE(observed->cleared_components.empty());

  owner.stop.reset();
  fixture.kernel->observe_component_states({owner, io});
  io.lifecycle = ComponentLifecycle::kPrepared;
  fixture.kernel->observe_component_states({owner, io});
  EXPECT_EQ(observed->cleared_components, std::vector<std::string>{"gripper.io"});
}








