// ---- K2 design tests: runner loss, rule hold, handover, children (§8, §11.3) ----
/// A cell whose one robot is an intrinsic direct-control target bound to the
/// captured Program (run 1, every group running); the runner reports the run.
struct K2HandoverCell final {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  std::unique_ptr<ResourceAddressedExecutionKernel> owner;
  std::optional<CellAdmissionClaimDTO> parent;
};

void k2_start_handover_cell(K2HandoverCell& cell) {
  auto direct = registration(
      make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular), cell.engine);
  direct.intrinsic_direct_control = true;
  ResourceAddressedExecutionKernelConfig config{kTestApplicationStartId,
                                                CellId("cell.test"), 8U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  cell.owner = make_uncaptured_kernel({direct}, cell.clock, cell.scheduler, cell.journal, config);
  auto& kernel = *cell.owner;
  const auto parent = claim_program_execution(kernel);
  ASSERT_TRUE(parent.ok()) << parent.error().message;
  cell.parent = parent.value();
  ASSERT_TRUE(kernel.register_program_run_capture(program_execution_capture()).ok());
  start_program_motion(kernel);
  const CellAdmissionReadinessSnapshotDTO running{
      true,
      ProgramCycleStatusDTO{2U, ProgramCycleStateDTO::kRunning, ProgramRunNumber(1U),
                            parent.value().claim_generation, std::nullopt},
      true,
      1U,
      1U,
      true,
      true,
      0U,
      0U,
      0U};
  ASSERT_TRUE(kernel.UpdateCellAdmissionReadiness(running).ok());
}

/// The manual move with the handover context of the current hold revision;
/// absent when the Kernel refuses the handover.
[[nodiscard]] std::optional<OperationIntentDTO> k2_handover_intent(K2HandoverCell& cell,
                                                                   std::string request_id) {
  auto manual = manual_motion_operation(std::move(request_id));
  const auto held = cell.owner->get_manual_program_handover(manual);
  if (!held.ok() || !held.value()) return std::nullopt;
  manual.manual_handover = ManualProgramHandoverContextDTO{
      ProgramRunNumber(1U), cell.parent->claim_generation, held.value()->hold_revision};
  return manual;
}

// §8 case 27 (review M1): runner loss holds every running node and freezes
// the run; Execute after it lowers the freeze only, so the node stays held
// until Resume.
TEST(ResourceAddressedExecutionKernelTest, ExecuteAfterRunnerLossDoesNotGrantMotion) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  auto owner = program_fence_kernel(clock, scheduler, engine, journal);
  auto& kernel = *owner;
  ASSERT_TRUE(ready_cell_admission(kernel).ok());
  const auto claim = claim_program_run(kernel, 1U);
  ASSERT_TRUE(claim.ok()) << claim.error().message;
  ASSERT_TRUE(kernel.register_program_run_capture(program_execution_capture()).ok());
  start_program_motion(kernel);
  const auto moving = kernel.execute(scoped_motion_operation("runner.loss.k2.motion"));
  ASSERT_TRUE(moving.ok()) << moving.error().message;
  engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);

  ProgramRunnerContactLossDTO loss{
      {2U, ProgramCycleStateDTO::kRunning, ProgramRunNumber(1U), claim.value().claim_generation,
       std::nullopt},
      "program_runner_liveness_probe",
      "connection refused", "program_runner_contact_lost"};
  CellAdmissionReadinessSnapshotDTO closed{
      false, loss.established_cycle, false, 1U, 0U, false, false, 0U, 0U, 0U};
  closed.program_runner_loss = loss;
  ASSERT_TRUE(kernel.UpdateCellAdmissionReadiness(closed).ok());
  ASSERT_TRUE(wait_until([&] { return engine.stop_calls.load() == 1; }));
  const auto lost = kernel.get_stop_stream_facts();
  ASSERT_TRUE(lost.program_run_hold.has_value());
  EXPECT_EQ(lost.program_run_hold->frozen, RunFrozenLevel::kRunnerLoss);
  // Frozen by runner loss: that event's requested kind and its Kernel label.
  EXPECT_EQ(lost.program_run_hold->frozen_kind,
            std::optional<StopKind>(StopKind::kRunnerLoss));
  ASSERT_TRUE(lost.program_run_hold->frozen_source_label.has_value());
  EXPECT_FALSE(lost.program_run_hold->frozen_source_label->empty());
  ASSERT_TRUE(lost.last_stop_event_id.has_value());
  ASSERT_TRUE(wait_stop_complete(kernel, *lost.last_stop_event_id));
  const auto held = kernel.get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(held.ok()) << held.error().message;
  EXPECT_EQ(node_state(held.value(), 0U), ProgramNodeHoldStateDTO::kHeld);

  // Execute: the freeze goes, the motion hold stays (S10, L3).
  const auto released = kernel.release_halt(ProgramRunNumber(1U), held.value().hold_revision);
  ASSERT_TRUE(released.ok()) << released.error().message;
  ASSERT_TRUE(released.value().has_value());
  EXPECT_EQ(released.value()->frozen, RunFrozenLevel::kNone);
  EXPECT_EQ(node_state(*released.value(), 0U), ProgramNodeHoldStateDTO::kHeld);
  EXPECT_GT(released.value()->hold_revision, held.value().hold_revision);
  const auto after = kernel.get_stop_stream_facts();
  ASSERT_TRUE(after.program_run_hold.has_value());
  EXPECT_EQ(after.program_run_hold->frozen, RunFrozenLevel::kNone);
  EXPECT_EQ(engine.stop_calls.load(), 1);
}

// §8 case 9: a rule hold joins an operator Stop; Resume is refused while the
// rule holds and allowed after it clears; Resume clears `held_by_rule`.
TEST(ResourceAddressedExecutionKernelTest, RuleHoldAndOperatorStopResumeWaitsForRule) {
  GlobalMotionRuleFixture fixture;
  auto& kernel = *fixture.kernel;
  ASSERT_TRUE(claim_program_execution(kernel).ok());
  ASSERT_TRUE(kernel.register_program_run_capture(program_execution_capture()).ok());
  start_program_motion(kernel);
  const auto operator_stop =
      kernel.stop_program_selection(program_selection_request("k2.rule.operator", "arm"));
  EXPECT_EQ(operator_stop.stop.applied, StopKind::kGroups);
  ASSERT_TRUE(operator_stop.state.has_value());
  EXPECT_EQ(node_state(*operator_stop.state, 0U), ProgramNodeHoldStateDTO::kHeld);

  ASSERT_TRUE(fixture.Publish(true).ok());
  ASSERT_TRUE(kernel.ProcessIoRuleEvidence().ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kTripped));
  const auto both = kernel.get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(both.ok()) << both.error().message;
  EXPECT_EQ(both.value().stopped_by_rule_id, std::optional<std::string>("global.guard"));
  EXPECT_EQ(node_state(both.value(), 0U), ProgramNodeHoldStateDTO::kHeld);
  EXPECT_EQ(node_state(both.value(), 1U), ProgramNodeHoldStateDTO::kHeld);
  const auto waiting = kernel.release_program_selection(
      program_selection_request("k2.rule.resume.early", "all"), both.value().hold_revision);
  ASSERT_FALSE(waiting.ok());
  EXPECT_EQ(waiting.error().code, "rule_holds");

  // S8: the rule clearing raises no event; the hold stays until Resume.
  ASSERT_TRUE(fixture.Publish(false).ok());
  ASSERT_TRUE(kernel.ProcessIoRuleEvidence().ok());
  ASSERT_TRUE(wait_global_rule_state(fixture, IoGlobalRuleState::kClear));
  const auto cleared = kernel.get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(cleared.ok());
  EXPECT_EQ(cleared.value().stopped_by_rule_id, std::optional<std::string>("global.guard"));
  EXPECT_FALSE(cleared.value().held_nodes.empty());
  const auto resumed = kernel.release_program_selection(
      program_selection_request("k2.rule.resume", "all"), cleared.value().hold_revision);
  ASSERT_TRUE(resumed.ok()) << resumed.error().message;
  EXPECT_TRUE(resumed.value().held_nodes.empty());
  EXPECT_FALSE(resumed.value().stopped_by_rule_id.has_value());
  EXPECT_GT(resumed.value().hold_revision, cleared.value().hold_revision);
}

// §8 case 23 (C3): a group Stop does not cover a manual handover move on
// that group's robot; the move keeps moving.
TEST(ResourceAddressedExecutionKernelTest, GroupStopLeavesHandoverMoving) {
  K2HandoverCell cell;
  k2_start_handover_cell(cell);
  auto& kernel = *cell.owner;
  (void)kernel.stop_program_selection(program_selection_request("k2.handover.hold", "arm"));
  const auto manual = k2_handover_intent(cell, "k2.handover.moving");
  ASSERT_TRUE(manual.has_value());
  const auto admitted = kernel.execute(*manual);
  ASSERT_TRUE(admitted.ok()) << admitted.error().message;
  ASSERT_TRUE(wait_until([&] { return cell.engine.execute_calls == 1; }));

  for (const auto* group : {"arm", "all"}) {
    SCOPED_TRACE(group);
    const auto stopped = kernel.stop_program_selection(
        program_selection_request(std::string("k2.handover.group.") + group, group));
    EXPECT_EQ(stopped.stop.applied, StopKind::kGroups);
    EXPECT_TRUE(stopped.stop.covered.empty());
  }
  EXPECT_EQ(cell.engine.stop_calls.load(), 0);
  const auto state = kernel.get_operation_state(admitted.value().operation_id);
  ASSERT_TRUE(state.ok());
  EXPECT_FALSE(state.value().stop_event_id.has_value());
  EXPECT_NE(state.value().state, OperationStateKind::kStopping);
}

// §8 case 23 (C4, PD-7): Resume is refused while a manual handover is on the
// robot being released. The handover's own cell-admission claim is a child
// of the Program claim, so the existing unsettled-child clause answers first
// (`program_children_unsettled`); C4 (`program_selection_manual_operation_active`)
// stands behind it.
TEST(ResourceAddressedExecutionKernelTest, ResumeRefusedWhileHandoverOnRobot) {
  K2HandoverCell cell;
  k2_start_handover_cell(cell);
  auto& kernel = *cell.owner;
  (void)kernel.stop_program_selection(program_selection_request("k2.c4.hold", "arm"));
  const auto manual = k2_handover_intent(cell, "k2.c4.moving");
  ASSERT_TRUE(manual.has_value());
  const auto admitted = kernel.execute(*manual);
  ASSERT_TRUE(admitted.ok()) << admitted.error().message;
  ASSERT_TRUE(wait_until([&] { return cell.engine.execute_calls == 1; }));
  const auto scope = kernel.get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(scope.ok());
  const auto resumed = kernel.release_program_selection(
      program_selection_request("k2.c4.resume", "arm"), scope.value().hold_revision);
  ASSERT_FALSE(resumed.ok());
  const auto reason = resumed.error().details.at("reason");
  EXPECT_EQ(reason, "program_children_unsettled");
  const auto still = kernel.get_program_execution_scope(ProgramRunNumber(1U));
  ASSERT_TRUE(still.ok());
  EXPECT_EQ(node_state(still.value(), 0U), ProgramNodeHoldStateDTO::kHeld);
  EXPECT_EQ(still.value().hold_revision, scope.value().hold_revision);
}

// L8 (APPROVED O2): no manual handover while the run is frozen; allowed
// again after Execute.
TEST(ResourceAddressedExecutionKernelTest, HaltBlocksManualHandoverUntilExecute) {
  K2HandoverCell cell;
  k2_start_handover_cell(cell);
  auto& kernel = *cell.owner;
  (void)kernel.stop_program_selection(program_selection_request("k2.l8.hold", "arm"));
  ASSERT_TRUE(k2_handover_intent(cell, "k2.l8.before").has_value());
  const auto halted = kernel.halt(full_stop_request("k2.l8.halt"));
  EXPECT_EQ(halted.applied, StopKind::kHalt);
  ASSERT_TRUE(wait_stop_complete(kernel, halted.event_id));

  auto manual = manual_motion_operation("k2.l8.during");
  const auto refused = kernel.get_manual_program_handover(manual);
  ASSERT_FALSE(refused.ok());
  EXPECT_EQ(refused.error().details.at("reason"), "manual_handover_program_halted");
  const auto unavailable = kernel.get_manual_control_availability(manual);
  ASSERT_TRUE(unavailable.ok());
  EXPECT_FALSE(unavailable.value().available);
  EXPECT_EQ(unavailable.value().unavailable_reason, "manual_handover_program_halted");

  const auto released = kernel.release_halt(ProgramRunNumber(1U), halted.hold_revision);
  ASSERT_TRUE(released.ok()) << released.error().message;
  ASSERT_TRUE(released.value().has_value());
  EXPECT_EQ(released.value()->frozen, RunFrozenLevel::kNone);
  const auto after = k2_handover_intent(cell, "k2.l8.after");
  ASSERT_TRUE(after.has_value());
  const auto admitted = kernel.execute(*after);
  ASSERT_TRUE(admitted.ok()) << admitted.error().message;
}

// Review M4: Resume keeps the existing unsettled Program-child clause: a held
// Program scene node claim on the selected node refuses it until settled.
TEST(ResourceAddressedExecutionKernelTest, ResumeRefusedWhileProgramChildUnsettled) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  ResourceAddressedExecutionKernelConfig config{kTestApplicationStartId,
                                                CellId("cell.test"), 8U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  config.cell_admission_settlement_validator = [](const auto&, const auto&) {
    return Result<void>::Ok();
  };
  auto owner = make_uncaptured_kernel(
      {registration(make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
                    engine)},
      clock, scheduler, journal, std::move(config));
  auto& kernel = *owner;
  const auto parent = claim_program_execution(kernel);
  ASSERT_TRUE(parent.ok()) << parent.error().message;
  auto capture = program_execution_capture();
  auto table = std::make_shared<ProgramExecutionTableDTO>(*capture.table);
  table->nodes.front().owner_api = "scene.carried_attachment";
  capture.table = table;
  ASSERT_TRUE(kernel.register_program_run_capture(std::move(capture)).ok());
  start_program_motion(kernel);
  const CellAdmissionReadinessSnapshotDTO idle{
      true,
      ProgramCycleStatusDTO{1U, ProgramCycleStateDTO::kIdleAfterReset, {}, {}, {}},
      true,
      1U,
      1U,
      true,
      true,
      0U,
      0U,
      0U};
  ASSERT_TRUE(kernel.UpdateCellAdmissionReadiness(idle).ok());
  const CellAdmissionClaimIntentDTO intent{
      CellAdmissionClaimKindDTO::kAuthoredScene,
      ApplicationRole::kAuthoredSceneOwner,
      std::nullopt,
      TestRequestKey("k2.child.scene.claim"),
      kernel.GetAuthoringAdmission().admission_generation,
      {},
      {},
      {},
      ProgramNodeAdmissionEvidenceDTO{ProgramRunNumber(1U), parent.value().claim_generation,
                                      "move", NodeAttemptNumber(1U), "scene.carried_attachment"}};
  const auto child = kernel.AcquireCellAdmissionClaim(intent);
  ASSERT_TRUE(child.ok()) << child.error().message;
  const auto stopped =
      kernel.stop_program_selection(program_selection_request("k2.child.stop", "arm"));
  ASSERT_TRUE(stopped.state.has_value());
  const auto refused = kernel.release_program_selection(
      program_selection_request("k2.child.resume", "arm"), stopped.state->hold_revision);
  ASSERT_FALSE(refused.ok());
  EXPECT_EQ(refused.error().details.at("reason"), "program_children_unsettled");

  const auto& value = child.value();
  ASSERT_TRUE(kernel
                  .ReleaseCellAdmissionClaim({value.intent.owner_role,
                                              value.intent.owner_transaction_id,
                                              value.intent.request_key,
                                              value.acquired_admission_generation,
                                              value.claim_generation,
                                              {CellAdmissionSettlementKindDTO::kOwnerCommit,
                                               ContentDigest(test_digest('0'))}})
                  .ok());
  const auto resumed = kernel.release_program_selection(
      program_selection_request("k2.child.resume.settled", "arm"), stopped.state->hold_revision);
  ASSERT_TRUE(resumed.ok()) << resumed.error().message;
  EXPECT_EQ(node_state(resumed.value(), 0U), ProgramNodeHoldStateDTO::kRunning);
}
// ---- end of K2 design tests ----

TEST(ResourceAddressedExecutionKernelTest, TwoArmsInOneCellEachKeepTheirLatestManualResult) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine_a;
  FakeParticipantEngine engine_b;
  FakeOperationJournal journal;
  const auto base = make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular);
  auto arm_a = registration(coordinated_occurrence(base, "a"), engine_a);
  auto arm_b = registration(coordinated_occurrence(base, "b"), engine_b);
  arm_a.intrinsic_direct_control = true;
  arm_b.intrinsic_direct_control = true;
  ResourceAddressedExecutionKernelConfig config{kTestApplicationStartId,
                                                CellId("cell.test"), 16U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  auto owner = make_unclaimed_kernel(
      {arm_a, arm_b}, clock, scheduler, journal, config);
  auto& kernel = *owner;
  ASSERT_TRUE(ready_cell_admission(kernel).ok());
  const auto target_of = [](const RuntimeParticipantExecutionRegistration& arm) {
    return ProgramTargetReferenceDTO{arm.binding.value().controllable_component_id,
                                     arm.binding.value().command_target_id};
  };
  const auto run_manual = [&](const RuntimeParticipantExecutionRegistration& arm,
                              FakeParticipantEngine& engine, std::string request) {
    auto intent = manual_motion_operation(std::move(request));
    retarget(intent.participants.front(), arm.binding.value().controllable_component_id,
             arm.binding.value().command_target_id);
    const auto accepted = kernel.execute(intent);
    EXPECT_TRUE(accepted.ok()) << accepted.error().message;
    if (!accepted.ok()) return OperationNumber(0U);
    engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kCompleted);
    EXPECT_TRUE(wait_until([&] {
      return kernel.reconcile_manual_operation_admission().ok() &&
             !kernel.get_operation_projection(accepted.value().operation_id).value().resident;
    }));
    return accepted.value().operation_id;
  };
  const auto first_a = run_manual(arm_a, engine_a, "manual.arm-a.1");
  const auto only_b = run_manual(arm_b, engine_b, "manual.arm-b.1");
  const auto latest_a = run_manual(arm_a, engine_a, "manual.arm-a.2");
  ASSERT_TRUE(first_a.nonzero() && only_b.nonzero() && latest_a.nonzero());

  const auto per_arm = kernel.get_latest_manual_operations({target_of(arm_a), target_of(arm_b)});
  ASSERT_EQ(per_arm.size(), 2U);
  EXPECT_EQ(per_arm[0].operation.operation_id, latest_a);
  EXPECT_EQ(per_arm[1].operation.operation_id, only_b);
  for (const auto& row : per_arm) {
    EXPECT_FALSE(row.resident);
    EXPECT_FALSE(row.operation.program_run_id.has_value());
  }
  EXPECT_EQ(kernel.get_latest_manual_operations({target_of(arm_b)}).front().operation.operation_id,
            only_b);
}

// Manager-Apply and authored-scene releases settle on the Kernel's identity
// and settlement-kind checks alone, with a validator that reads no store.
TEST(ResourceAddressedExecutionKernelTest, ManagerApplyAndSceneReleasesNeedNoOwnerStore) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  ResourceAddressedExecutionKernelConfig config{kTestApplicationStartId,
                                                CellId("cell.test"), 16U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  unsigned validator_calls = 0U;
  // Accepts authoring, Manager-Apply and authored-scene releases; refuses others.
  config.cell_admission_settlement_validator = [&](const auto& claim, const auto&) {
    ++validator_calls;
    switch (claim.intent.claim_kind) {
      case CellAdmissionClaimKindDTO::kAuthoringMutation:
      case CellAdmissionClaimKindDTO::kManagerApply:
      case CellAdmissionClaimKindDTO::kAuthoredScene:
        return Result<void>::Ok();
      default:
        return Result<void>::Err(
            ErrorDTO{"invariant_violation", "settlement reader unavailable", {}});
    }
  };
  auto kernel_heap_test_owner = make_unclaimed_kernel(
      {registration(
          make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, journal, std::move(config));
  auto& kernel = *kernel_heap_test_owner;
  const auto settle = [&](CellAdmissionClaimKindDTO kind, ApplicationRole role,
                          std::optional<CellAdmissionOwnerTransactionId> id,
                          std::optional<CellAdmissionOwnerTransactionId> foreign_id,
                          CellAdmissionSettlementKindDTO settlement, const char* request) {
    ASSERT_TRUE(ready_cell_admission(kernel).ok());
    const CellAdmissionClaimIntentDTO intent{
        kind, role, id, TestRequestKey(request),
        kernel.GetAuthoringAdmission().admission_generation, {}, std::nullopt, std::nullopt};
    const auto claim = kernel.AcquireCellAdmissionClaim(intent);
    ASSERT_TRUE(claim.ok()) << request << ": " << claim.error().message;
    const CellAdmissionClaimReleaseDTO release{
        role, id, TestRequestKey(std::string(request) + ".release"),
        claim.value().acquired_admission_generation, claim.value().claim_generation,
        {settlement, ContentDigest(test_digest('3'))}};
    const auto calls = validator_calls;
    if (foreign_id) {
      auto foreign = release;
      foreign.owner_transaction_id = foreign_id;
      EXPECT_EQ(kernel.ReleaseCellAdmissionClaim(foreign).error().code, "stale_generation")
          << request;
    }
    auto wrong_generation = release;
    wrong_generation.claim_generation =
        CellAdmissionClaimGeneration(claim.value().claim_generation.value() + 100U);
    EXPECT_EQ(kernel.ReleaseCellAdmissionClaim(wrong_generation).error().code, "stale_generation")
        << request;
    EXPECT_EQ(validator_calls, calls) << request;
    const auto released = kernel.ReleaseCellAdmissionClaim(release);
    ASSERT_TRUE(released.ok()) << request << ": " << released.error().message;
    EXPECT_EQ(validator_calls, calls + 1U) << request;
    EXPECT_FALSE(kernel.ReadHeldCellAdmissionClaim(kind).has_value()) << request;
  };
  settle(CellAdmissionClaimKindDTO::kManagerApply, ApplicationRole::kManager,
         CellAdmissionOwnerTransactionId(ApplyId(5U)),
         CellAdmissionOwnerTransactionId(ApplyId(6U)),
         CellAdmissionSettlementKindDTO::kTerminalEffectsSettled, "store-absent.apply");
  settle(CellAdmissionClaimKindDTO::kAuthoredScene, ApplicationRole::kAuthoredSceneOwner,
         std::nullopt, std::nullopt, CellAdmissionSettlementKindDTO::kOwnerCommit,
         "store-absent.scene");
}

// ---- Journal writer: actions never wait for the disk ------------------------

[[nodiscard]] RuntimeParticipantExecutionRegistration writer_test_arm(
    FakeParticipantEngine& engine) {
  return registration(make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular),
                      engine);
}

// A stalled disk: an Execute is dispatched, its feedback reaches its terminal
// and its acknowledgement applies; no row is written until the writer moves,
// then the rows follow in action order.
TEST(ResourceAddressedExecutionKernelTest, OperationsProceedWithTheJournalWriterBlocked) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  auto owner = make_claimed_kernel({writer_test_arm(engine)}, clock, scheduler, journal,
                                   {kTestApplicationStartId, CellId("cell.test"), 16U});
  auto& kernel = *owner;
  ASSERT_TRUE(drain_journal(kernel));
  std::vector<std::string> rows_before;
  {
    std::lock_guard lock(journal.mutex);
    rows_before = journal.calls;
  }
  StalledJournal stalled(journal);

  const auto accepted = kernel.execute(motion_operation("writer.blocked.execute"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  ASSERT_TRUE(wait_until([&] { return engine.execute_calls.load() == 1; }));
  engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
  engine.emit_transition(ExecutionState::kExecuting, ExecutionState::kCompleted);
  const auto completed = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(completed.ok()) << completed.error().message;
  EXPECT_EQ(completed.value().state, OperationStateKind::kCompleted);
  const auto acknowledged = kernel.acknowledge_completed(
      control_request("writer.blocked.ack", accepted.value(),
                      completed.value().operation_revision.value()));
  ASSERT_TRUE(acknowledged.ok()) << acknowledged.error().message;
  ASSERT_TRUE(wait_until([&] {
    const auto projection = kernel.get_operation_projection(accepted.value().operation_id);
    return projection.ok() && !projection.value().resident;
  }));
  EXPECT_EQ(engine.acknowledge_calls.load(), 1);
  {
    std::lock_guard lock(journal.mutex);
    EXPECT_EQ(journal.calls, rows_before);
  }

  stalled.Release();
  ASSERT_TRUE(drain_journal(kernel));
  EXPECT_FALSE(kernel.get_operation_journal_write_fault().has_value());
  std::lock_guard lock(journal.mutex);
  const auto accepted_row = std::find(journal.calls.begin(), journal.calls.end(), "operation_accepted");
  const auto control_row = std::find(journal.calls.begin(), journal.calls.end(), "control_accepted");
  ASSERT_NE(accepted_row, journal.calls.end());
  ASSERT_NE(control_row, journal.calls.end());
  EXPECT_LT(accepted_row, control_row);
}

// A speed change is stored, its step runs and it replies with the writer
// stalled; the status reads "applied" at the next reconcile pass; its row
// follows once the writer moves (OD-149).
TEST(ResourceAddressedExecutionKernelTest, SpeedChangeRepliesWithTheJournalWriterBlocked) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  auto owner = make_claimed_kernel({writer_test_arm(engine)}, clock, scheduler, journal,
                                   {kTestApplicationStartId, CellId("cell.test"), 16U});
  auto& kernel = *owner;
  const auto accepted = kernel.execute(motion_operation("writer.blocked.scaled"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  ASSERT_TRUE(drain_journal(kernel));
  StalledJournal stalled(journal);
  // The Executing row holds the writer in its batch.
  engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
  const auto scale_calls = engine.runtime_scale_calls.load();
  const auto scaled = kernel.set_runtime_scale_control(
      runtime_scale_control_request("writer.blocked.scale", 0U, 0.5));
  ASSERT_TRUE(scaled.ok()) << scaled.error().message;
  ASSERT_FALSE(engine.StoredRuntimeScaleSettings().empty());
  EXPECT_DOUBLE_EQ(engine.StoredRuntimeScaleSettings().back().first, 0.5);
  // The disk does not hold the step nor the status.
  EXPECT_EQ(engine.runtime_scale_calls.load(), scale_calls + 1);
  EXPECT_FALSE(
      StopControlExecutorTestAccess::RuntimeScalePending(kernel, accepted.value().operation_id));
  ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
  const auto status = kernel.get_runtime_scale(accepted.value().operation_id);
  ASSERT_TRUE(status.ok()) << status.error().message;
  EXPECT_EQ(status.value().runtime_scale_generation, RuntimeScaleGeneration(1U));
  EXPECT_EQ(status.value().state, RuntimeScaleApplicationState::kApplied);
  {
    std::lock_guard lock(journal.mutex);
    EXPECT_EQ(std::count(journal.calls.begin(), journal.calls.end(), "runtime_scale_accepted"), 0);
  }
  stalled.Release();
  ASSERT_TRUE(drain_runtime_scale(kernel));
  std::lock_guard lock(journal.mutex);
  EXPECT_EQ(std::count(journal.calls.begin(), journal.calls.end(), "runtime_scale_accepted"), 1);
}

// 70 Stops (one operation Stop, then Stop alls) are accepted and complete
// with the writer stalled; every acceptance and completion row follows.
TEST(ResourceAddressedExecutionKernelTest, StopsAndStopAllsCompleteWithTheJournalWriterBlocked) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  auto owner = make_claimed_kernel({writer_test_arm(engine)}, clock, scheduler, journal,
                                   {kTestApplicationStartId, CellId("cell.test"), 128U});
  auto& kernel = *owner;
  const auto accepted = kernel.execute(motion_operation("writer.blocked.stopped"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
  ASSERT_TRUE(drain_journal(kernel));
  StalledJournal stalled(journal);

  std::vector<StopEventId> events;
  const auto stopped = kernel.stop(stop_request("writer.blocked.stop", accepted.value(), 1U));
  events.push_back(stopped.event_id);
  ASSERT_TRUE(wait_stop_complete(kernel, stopped.event_id));
  EXPECT_EQ(kernel.read_stop(stopped.event_id).value().result, StopEventResult::kStopped);
  for (int index = 1; index < 70; ++index) {
    const auto all = kernel.stop_all(full_stop_request("writer.blocked.stop_all." + std::to_string(index)));
    EXPECT_EQ(all.applied, StopKind::kStopAll);
    events.push_back(all.event_id);
    ASSERT_TRUE(wait_stop_complete(kernel, all.event_id));
  }
  EXPECT_EQ(journal.stop_acceptance_calls.load(), 0);
  EXPECT_FALSE(kernel.get_cell_latch().latched);

  stalled.Release();
  ASSERT_TRUE(drain_journal(kernel));
  std::lock_guard lock(journal.mutex);
  EXPECT_EQ(journal.stop_acceptance_calls.load(), 70);
  EXPECT_EQ(journal.stop_terminal_calls.load(), 70);
  auto acceptances = journal.projected_stop_acceptances;
  auto terminals = journal.projected_stop_terminals;
  std::sort(events.begin(), events.end());
  std::sort(acceptances.begin(), acceptances.end());
  std::sort(terminals.begin(), terminals.end());
  EXPECT_EQ(acceptances, events);
  EXPECT_EQ(terminals, events);
}

// Rows follow the action order: two operations accepted one after the other
// keep that order, and each operation's rows keep their capture order (its
// acceptance first, its terminal last) under concurrent feedback.
TEST(ResourceAddressedExecutionKernelTest, JournalRowsFollowTheActionOrder) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine first_engine;
  FakeParticipantEngine second_engine;
  FakeOperationJournal journal;
  const auto first_binding =
      make_binding("arm", "execution.trajectory.execute", CoordinateKind::kAngular);
  const auto second_binding = second_same_program_occurrence(first_binding);
  auto owner = make_claimed_kernel(
      {registration(first_binding, first_engine), registration(second_binding, second_engine)},
      clock, scheduler, journal, {kTestApplicationStartId, CellId("cell.test"), 16U});
  auto& kernel = *owner;
  ASSERT_TRUE(drain_journal(kernel));
  const auto first = kernel.execute(motion_operation("order.first"));
  ASSERT_TRUE(first.ok()) << first.error().message;
  auto second_intent = motion_operation("order.second");
  second_intent.program_binding_id = second_binding.value().program_binding_id;
  retarget(second_intent.participants.front(), second_binding.value().controllable_component_id,
           second_binding.value().command_target_id);
  const auto second = kernel.execute(second_intent);
  ASSERT_TRUE(second.ok()) << second.error().message;
  const auto feedback = [](FakeParticipantEngine& engine) {
    engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
    engine.emit_transition(ExecutionState::kExecuting, ExecutionState::kCompleted);
  };
  auto first_feedback = std::async(std::launch::async, [&] { feedback(first_engine); });
  auto second_feedback = std::async(std::launch::async, [&] { feedback(second_engine); });
  first_feedback.get();
  second_feedback.get();
  ASSERT_TRUE(drain_journal(kernel));

  std::lock_guard lock(journal.mutex);
  const auto rows_of = [&](const OperationNumber& id) {
    std::vector<OperationStateDTO> rows;
    for (const auto& state : journal.states)
      if (state.operation_id == id) rows.push_back(state);
    return rows;
  };
  const auto first_row = std::find_if(journal.states.begin(), journal.states.end(),
      [&](const auto& state) { return state.operation_id == first.value().operation_id; });
  const auto second_row = std::find_if(journal.states.begin(), journal.states.end(),
      [&](const auto& state) { return state.operation_id == second.value().operation_id; });
  ASSERT_NE(first_row, journal.states.end());
  ASSERT_NE(second_row, journal.states.end());
  EXPECT_LT(first_row, second_row);
  for (const auto& id : {first.value().operation_id, second.value().operation_id}) {
    const auto rows = rows_of(id);
    ASSERT_GE(rows.size(), 2U);
    EXPECT_EQ(rows.front().state, OperationStateKind::kResolving);
    EXPECT_EQ(rows.back().state, OperationStateKind::kCompleted);
    EXPECT_EQ(std::adjacent_find(rows.begin(), rows.end(),
                                 [](const auto& earlier, const auto& later) {
                                   return earlier.journal_capture_order >
                                          later.journal_capture_order;
                                 }),
              rows.end());
  }
}

// Kernel destruction writes every posted record before the writer stops,
// also when the writer is busy with an earlier batch.
TEST(ResourceAddressedExecutionKernelTest, KernelDestructionWritesEveryPostedRecord) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  auto kernel = make_claimed_kernel({writer_test_arm(engine)}, clock, scheduler, journal,
                                    {kTestApplicationStartId, CellId("cell.test"), 16U});
  const auto accepted = kernel->execute(motion_operation("writer.shutdown"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  ASSERT_TRUE(drain_journal(*kernel));
  HeldSettlementCall writer;
  journal.SetRecordHook([hold = writer.Blocker(),
                         held = std::make_shared<std::atomic_bool>()](std::string_view kind) {
    if (kind == "state:subordinate_state_observed" && !held->exchange(true)) hold();
  });
  engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
  ASSERT_TRUE(writer.Entered());
  engine.emit_transition(ExecutionState::kExecuting, ExecutionState::kCompleted);
  auto retiring = std::async(std::launch::async, [owner = kernel.release()] { delete owner; });
  writer.Release();
  retiring.get();
  journal.SetRecordHook({});
  ASSERT_FALSE(journal.states.empty());
  EXPECT_EQ(journal.states.back().operation_id, accepted.value().operation_id);
  EXPECT_EQ(journal.states.back().state, OperationStateKind::kCompleted);
}

// A write error starts a loss episode: the fault is set and one line is
// logged; the next batch that writes everything and leaves the queue empty
// ends it and clears the fault. A later error starts a new episode.
TEST(ResourceAddressedExecutionKernelTest, JournalWriteErrorSetsTheFaultUntilACleanBatchEndsIt) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  auto owner = make_claimed_kernel({writer_test_arm(engine)}, clock, scheduler, journal,
                                   {kTestApplicationStartId, CellId("cell.test"), 16U});
  auto& kernel = *owner;
  ASSERT_TRUE(drain_journal(kernel));
  ::testing::internal::CaptureStderr();
  {
    journal.SetFailNextKind("operation_accepted");
    journal.hold_after_failure = true;
  }
  const auto accepted = kernel.execute(motion_operation("writer.fault.once"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  ASSERT_TRUE(wait_until([&] { return kernel.get_operation_journal_write_fault().has_value(); }));
  const auto fault = kernel.get_operation_journal_write_fault();
  EXPECT_EQ(fault->write_kind, "operation_accepted");
  EXPECT_EQ(fault->error.code, "operation_journal_test_failure");
  EXPECT_EQ(fault->operation_id, std::optional(accepted.value().operation_id));

  // Motion goes on while the fact is set; its rows end the episode.
  engine.emit_transition(ExecutionState::kPlanning, ExecutionState::kExecuting);
  EXPECT_EQ(kernel.get_operation_journal_write_fault(), fault);
  journal.Unblock();
  ASSERT_TRUE(drain_journal(kernel));
  EXPECT_FALSE(kernel.get_operation_journal_write_fault().has_value());
  {
    std::lock_guard lock(journal.mutex);
    ASSERT_FALSE(journal.states.empty());
    EXPECT_EQ(journal.states.back().state, OperationStateKind::kExecuting);
  }
  journal.SetFailNextKind("state:subordinate_state_observed");
  journal.hold_after_failure = true;
  engine.emit_transition(ExecutionState::kExecuting, ExecutionState::kCompleted);
  ASSERT_TRUE(wait_until([&] { return kernel.get_operation_journal_write_fault().has_value(); }));
  EXPECT_EQ(kernel.get_operation_journal_write_fault()->write_kind, "subordinate_state_observed");
  journal.Unblock();
  ASSERT_TRUE(drain_journal(kernel));
  const auto output = ::testing::internal::GetCapturedStderr();
  EXPECT_EQ(kernel.get_operation_state(accepted.value().operation_id).value().state,
            OperationStateKind::kCompleted);
  // One line per episode.
  for (const std::string line :
       {"manyforge_journal_write_fault kind=operation_accepted code=operation_journal_test_failure\n",
        "manyforge_journal_write_fault kind=subordinate_state_observed "
        "code=operation_journal_test_failure\n"}) {
    const auto first = output.find(line);
    ASSERT_NE(first, std::string::npos) << output;
    EXPECT_EQ(output.find(line, first + line.size()), std::string::npos) << output;
  }
}

// A full queue drops the newest ordinary record: that starts a loss episode
// (the fault at once, one line). Motion stays admitted, the Stop reserve still
// takes Stop rows, writing the queue empty ends the episode, and shutdown
// counts the records not written.
TEST(ResourceAddressedExecutionKernelTest, DroppedRecordsStartALossEpisodeThatAnEmptyQueueEnds) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  auto direct = writer_test_arm(engine);
  direct.intrinsic_direct_control = true;
  ResourceAddressedExecutionKernelConfig config{kTestApplicationStartId, CellId("cell.test"), 8U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  config.cell_admission_settlement_validator = [](const auto&, const auto&) {
    return Result<void>::Ok();
  };
  auto owner = make_unclaimed_kernel({direct}, clock, scheduler, journal, std::move(config));
  auto& kernel = *owner;
  ASSERT_TRUE(ready_cell_admission(kernel).ok());
  ASSERT_TRUE(drain_journal(kernel));
  // Each authoring claim posts one row when acquired and one when released.
  const auto acquire = [&](const std::string& name) {
    return kernel.AcquireCellAdmissionClaim(
        {CellAdmissionClaimKindDTO::kAuthoringMutation, ApplicationRole::kAuthoringOwner,
         std::nullopt, TestRequestKey(name), kernel.GetAuthoringAdmission().admission_generation,
         {}, std::nullopt, std::nullopt});
  };
  const auto release = [&](const CellAdmissionClaimDTO& held) {
    return kernel.ReleaseCellAdmissionClaim(
        {held.intent.owner_role, held.intent.owner_transaction_id, held.intent.request_key,
         held.acquired_admission_generation, held.claim_generation,
         {CellAdmissionSettlementKindDTO::kOwnerCommit, ContentDigest(test_digest('0'))}});
  };
  std::size_t batches = 0U;
  {
    std::lock_guard lock(journal.mutex);
    batches = journal.batches.size();
  }
  // The writer takes the first row and is held there; the queue is empty.
  journal.Block();
  const auto held = acquire("writer.full.claim");
  ASSERT_TRUE(held.ok()) << held.error().message;
  ASSERT_TRUE(journal.WaitBatchesEntered(batches + 1U));
  ASSERT_TRUE(release(held.value()).ok());
  // 1 + 2 * 2,048 rows: the last release finds the 4,096 places taken.
  for (int index = 0; index < 2048; ++index) {
    const auto claim = acquire("writer.full.claim." + std::to_string(index));
    ASSERT_TRUE(claim.ok()) << claim.error().message;
    ASSERT_TRUE(release(claim.value()).ok());
  }
  EXPECT_EQ(StopControlExecutorTestAccess::JournalQueueSize(kernel), 4096U);
  const auto fault = kernel.get_operation_journal_write_fault();
  ASSERT_TRUE(fault.has_value());
  EXPECT_EQ(fault->write_kind, "cell_claim_released");
  EXPECT_EQ(fault->error.code, "operation_journal_records_lost");
  EXPECT_TRUE(fault->queue_full);  // OD-215: the disk check's level

  // Motion admission stays open while the fact is set.
  const auto motion = kernel.execute(manual_motion_operation("writer.full.motion"));
  ASSERT_TRUE(motion.ok()) << motion.error().message;
  EXPECT_TRUE(wait_until([&] { return engine.execute_calls.load() == 1; }));
  // The Stop reserve still takes the Stop's rows.
  const auto stopped = kernel.stop_all(full_stop_request("writer.full.stop_all"));
  ASSERT_TRUE(wait_stop_complete(kernel, stopped.event_id));
  EXPECT_TRUE(kernel.get_operation_journal_write_fault().has_value());

  ::testing::internal::CaptureStderr();
  journal.Unblock();
  const bool drained = drain_journal(kernel);
  const auto output = ::testing::internal::GetCapturedStderr();
  ASSERT_TRUE(drained);
  const std::string line =
      "manyforge_journal_write_fault kind=cell_claim_released code=operation_journal_records_lost\n";
  const auto first = output.find(line);
  ASSERT_NE(first, std::string::npos) << output;
  EXPECT_EQ(output.find("manyforge_journal_write_fault", first + line.size()), std::string::npos)
      << output;
  // The batch that wrote the queue empty ended the episode.
  EXPECT_FALSE(kernel.get_operation_journal_write_fault().has_value());
  std::uint64_t dropped = 0U;
  {
    std::lock_guard lock(journal.mutex);
    EXPECT_EQ(journal.projected_stop_acceptances, std::vector<StopEventId>{stopped.event_id});
    EXPECT_EQ(journal.projected_stop_terminals, std::vector<StopEventId>{stopped.event_id});
    dropped = journal.dropped_records;
  }
  EXPECT_GE(dropped, 1U);

  ::testing::internal::CaptureStderr();
  owner.reset();
  const auto shutdown = ::testing::internal::GetCapturedStderr();
  const std::string summary = "manyforge_fault code=operation_journal_records_lost not_written=" +
                              std::to_string(dropped) + " undrained=0\n";
  const auto reported = shutdown.find(summary);
  ASSERT_NE(reported, std::string::npos) << shutdown;
  EXPECT_EQ(shutdown.find(summary, reported + summary.size()), std::string::npos) << shutdown;
  // OD-187 (3): the records still to write are logged when the drain
  // starts, before the summary (and before anything outside could cut it).
  const auto queued = shutdown.find("manyforge_journal_drain queued=");
  ASSERT_NE(queued, std::string::npos) << shutdown;
  EXPECT_LT(queued, reported) << shutdown;
}

// OD-215: the journal's "queue full" level ends when a batch leaves the queue
// empty, even when a write of that batch failed (the loss episode, and its
// alarm, go on; a store failing for another reason cannot hold the stop).
