// A cell claim is acquired and released in memory with the writer stalled;
// its two rows follow in that order.
TEST(ResourceAddressedExecutionKernelTest, CellClaimAcquiresAndReleasesWithTheJournalWriterBlocked) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  ResourceAddressedExecutionKernelConfig config{kTestApplicationStartId, CellId("cell.test"), 16U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  config.cell_admission_settlement_validator = [](const auto&, const auto&) {
    return Result<void>::Ok();
  };
  auto owner = make_unclaimed_kernel({writer_test_arm(engine)}, clock, scheduler, journal,
                                     std::move(config));
  auto& kernel = *owner;
  ASSERT_TRUE(ready_cell_admission(kernel).ok());
  ASSERT_TRUE(drain_journal(kernel));
  std::vector<std::string> rows_before;
  {
    std::lock_guard lock(journal.mutex);
    rows_before = journal.calls;
  }
  StalledJournal stalled(journal);

  const CellAdmissionClaimIntentDTO intent{CellAdmissionClaimKindDTO::kAuthoringMutation,
                                           ApplicationRole::kAuthoringOwner,
                                           std::nullopt,
                                           TestRequestKey("writer.blocked.claim"),
                                           kernel.GetAuthoringAdmission().admission_generation,
                                           {},
                                           std::nullopt,
                                           std::nullopt};
  const auto claim = kernel.AcquireCellAdmissionClaim(intent);
  ASSERT_TRUE(claim.ok()) << claim.error().message;
  const auto& held = claim.value();
  const auto released = kernel.ReleaseCellAdmissionClaim(
      {held.intent.owner_role, held.intent.owner_transaction_id, held.intent.request_key,
       held.acquired_admission_generation, held.claim_generation,
       {CellAdmissionSettlementKindDTO::kOwnerCommit, ContentDigest(test_digest('0'))}});
  ASSERT_TRUE(released.ok()) << released.error().message;
  EXPECT_FALSE(
      kernel.ReadHeldCellAdmissionClaim(CellAdmissionClaimKindDTO::kAuthoringMutation).has_value());
  {
    std::lock_guard lock(journal.mutex);
    EXPECT_EQ(journal.calls, rows_before);
  }

  stalled.Release();
  ASSERT_TRUE(drain_journal(kernel));
  std::lock_guard lock(journal.mutex);
  const auto acquired_row =
      std::find(journal.calls.begin(), journal.calls.end(), "cell_admission_acquired");
  const auto released_row =
      std::find(journal.calls.begin(), journal.calls.end(), "cell_admission_released");
  ASSERT_NE(acquired_row, journal.calls.end());
  ASSERT_NE(released_row, journal.calls.end());
  EXPECT_LT(acquired_row, released_row);
}

